INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_330096755ea0','bk_ncert_english','10-1-the-lost-child','10.1 The Lost Child',NULL,'public',23,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a57a86f594e','ch_330096755ea0','text','{"text": "IT was the festival of spring. From the wintry shades of narrow lanes and alleys emerged a gaily clad humanity. Some walked, some rode on horses, others sat, being carried in bamboo and bullock carts. One little boy ran between his father’s legs, brimming over with life and laughter."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e9ad88bafbb','ch_330096755ea0','text','{"text": "‘Come, child, come,’ called his parents, as he lagged behind, fascinated by the toys in the shops that lined the way."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f266e7adb9a7','ch_330096755ea0','text','{"text": "He hurried towards his parents, his feet obedient to their call, his eyes still lingering on the receding toys. As he came to where they had stopped to wait for him, he could not suppress the desire of his heart, even though he well knew the old, cold stare of refusal in their eyes."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_642c0addaa9a','ch_330096755ea0','text','{"text": "‘I want that toy,’ he pleaded."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_778a6eb72d10','ch_330096755ea0','text','{"text": "His father looked at him red-eyed, in his familiar tyrant’s way. His mother, melted by the free spirit of the day was tender and, giving him her finger to hold, said, ‘Look, child, what is before you!’ It was a flowering mustard-field, pale like melting gold as it swept across miles and miles of even land. A group of dragon-flies were bustling about on their gaudy purple wings, intercepting the flight of a lone black bee or butterfly in search of sweetness from the flowers."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d542ef669b1','ch_330096755ea0','text','{"text": "The child followed them in the air with his gaze, till one of them would still its wings and rest, and he would try to catch it. But it would go fluttering, flapping, up into the air, when he had almost caught it in his hands. Then his mother gave a cautionary call:"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f159dd270a2a','ch_330096755ea0','text','{"text": "‘Come, child, come, come on to the footpath.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abe9c800bcdb','ch_330096755ea0','text','{"text": "He ran towards his parents gaily and walked abreast of them for a while, being, however, soon left behind, attracted by the little insects and worms along the footpath that were teeming out from their hiding places to enjoy the sunshine."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ebea6681e44','ch_330096755ea0','text','{"text": "‘Come, child, come!’ his parents called from the shade of a grove where they had seated themselves on the edge of a well."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_996c9e4105df','ch_330096755ea0','text','{"text": "He ran towards them. A shower of young flowers fell upon the child as he entered the grove, and, forgetting his parents, he began to gather the raining petals in his hands. But lo! he heard the cooing of doves and ran towards his parents, shouting, ‘The dove! The dove!’ The raining petals dropped from his forgotten hands."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55dd1ac67adf','ch_330096755ea0','text','{"text": "‘Come, child, come!’ they called to the child, who had now gone running in wild capers round the banyan tree, and gathering him up they took the narrow, winding footpath which led to the fair through the mustard fields."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f9faa27f73a','ch_330096755ea0','text','{"text": "As they neared the village the child could see many other footpaths full of throngs, converging to the whirlpool of the fair, and felt at once repelled and fascinated by the confusion of the world he was entering. A sweetmeat seller hawked, ‘gulab-jaman, rasagulla, burfi, jalebi,’ at the corner of the entrance and a crowd pressed round his counter at the foot of an architecture of many coloured sweets, decorated with leaves of silver and gold."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36c1aacb2839','ch_330096755ea0','text','{"text": "The child stared openeyed and his mouth watered for the burfi that was his favourite sweet."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc2322b457f3','ch_330096755ea0','text','{"text": "‘I want that burfi,’ he slowly murmured."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_500588bab167','ch_330096755ea0','text','{"text": "But he half knew as he begged that his plea would not be heeded because his parents would say he was greedy. So without waiting for an answer he moved on. A flower-seller hawked, ‘A garland of gulmohur, a garland of gulmohur!’ The child seemed irresistibly drawn. He went towards the basket where the flowers lay heaped and half murmured, ‘I want that garland.’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_021e2ae07918','ch_330096755ea0','text','{"text": "But he well knew his parents would refuse to buy him those flowers because they would say that they were cheap. So, without waiting for an answer, he moved on. A man stood holding a pole with yellow, red, green and purple balloons flying from it. The child was simply carried away by the rainbow glory of their silken colours and he was filled with an overwhelming desire to possess them all."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c8f85dd20a5','ch_330096755ea0','text','{"text": "But he well knew his parents would never buy him the balloons because they would say he was too old to play with such toys. So he walked on farther. A snake-charmer stood playing a flute to a snake which coiled itself in a basket, its head raised in a graceful bend like the neck of a swan, while the music stole into its invisible ears like the gentle rippling of an invisible waterfall. The child went towards the snake-charmer."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_633a817d0276','ch_330096755ea0','text','{"text": "But, knowing his parents had forbidden him to hear such coarse music as the snake-charmer played, he proceeded farther. There was a roundabout in full swing. Men, women and children, carried away in a whirling motion, shrieked and cried with dizzy laughter. The child watched them intently and then he made a bold request:"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6b8cf3d0d2d','ch_330096755ea0','text','{"text": "‘I want to go on the roundabout, please, Father, Mother.’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_935564c36473','ch_330096755ea0','text','{"text": "There was no reply. He turned to look at his parents. They were not there, ahead of him. He turned to look on either side. They were not there. He looked behind. There was no sign of them. A full, deep cry rose within his dry throat and with a sudden jerk of his body he ran from where he stood, crying in real fear, ‘Mother, Father.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d746254112a','ch_330096755ea0','text','{"text": "Tears rolled down from his eyes, hot and fierce; his flushed face was convulsed with fear. Panic-stricken, he ran to one side first, then to the other, hither and thither in all directions, knowing not where to go."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_707d9db100de','ch_330096755ea0','text','{"text": "‘Mother, Father,’ he wailed."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f951b24a7d4','ch_330096755ea0','text','{"text": "His yellow turban came untied and his clothes became muddy. Having run to and fro in a rage of running for a while, he stood defeated, his cries suppressed into sobs. At little distances on the green grass he could see, through his filmy eyes, men and women talking. He tried to look intently among the patches of bright yellow clothes, but there was no sign of his father and mother among these people, who seemed to laugh and talk just for the sake of laughing and talking."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4df59d35d646','ch_330096755ea0','text','{"text": "He ran quickly again, this time to a shrine to which people seemed to be crowding. Every little inch of space here was congested with men, but he ran through people’s legs, his little sob lingering:"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb67be1d80eb','ch_330096755ea0','text','{"text": "‘Mother, Father!’ Near the entrance to the temple, however, the crowd became very thick:"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13c143dbaea9','ch_330096755ea0','text','{"text": "men jostled each other, heavy men, with flashing, murderous eyes and hefty shoulders."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a346cd1678b','ch_330096755ea0','text','{"text": "The poor child struggled to thrust a way between their feet but, knocked to and fro by their brutal movements, he might have been trampled underfoot, had he not shrieked at the highest pitch of his voice, ‘Father, Mother!’ A man in the surging crowd heard his cry and, stooping with great difficulty, lifted him up in his arms."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_318b3d04a887','ch_330096755ea0','text','{"text": "‘How did you get here, child? Whose baby are you?’ the man asked as he steered clear of the mass."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0255b1c51983','ch_330096755ea0','text','{"text": "The child wept more bitterly than ever now and only cried, ‘I want my mother, I want my father!’ The man tried to soothe him by taking him to the roundabout."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc827e5f1a9b','ch_330096755ea0','text','{"text": "‘Will you have a ride on the horse?’ he gently asked as he approached the ring."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1afb43da1725','ch_330096755ea0','text','{"text": "The child’s throat tore into a thousand shrill sobs and he only shouted, ‘I want my mother, I want my father!’ The man headed towards the place where the snake-charmer still played on the flute to the swaying cobra."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f197c8944720','ch_330096755ea0','text','{"text": "‘Listen to that nice music, child!’ he pleaded. But the child shut his ears with his fingers and shouted his double-pitched strain:"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ef15ed433c0','ch_330096755ea0','text','{"text": "‘I want my mother, I want my father!’ The man took him near the balloons, thinking the bright colours of the balloons would distract the child’s attention and quieten him."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eec50ac06f68','ch_330096755ea0','text','{"text": "‘Would you like a rainbowcoloured balloon?’ he persuasively asked."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ee2fe5234dc','ch_330096755ea0','text','{"text": "The child turned his eyes from the flying balloons and just sobbed, ‘I want my mother, I want my father!’ The man, still trying to make the child happy, bore him to the gate where the flower-seller sat."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49f014bbc1a3','ch_330096755ea0','text','{"text": "‘Look! Can you smell those nice flowers, child! Would you like a garland to put round your neck?’ The child turned his nose away from the basket and reiterated his sob, ‘I want my mother, I want my father!’ Thinking to humour his disconsolate charge by a gift of sweets, the man took him to the counter of the sweet shop."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51fc9d547e88','ch_330096755ea0','text','{"text": "‘What sweets would you like, child?’ he asked."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ddea84bde7b','ch_330096755ea0','text','{"text": "The child turned his face from the sweet shop and only sobbed, ‘I want my mother, I want my father!’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b971bed40019','ch_330096755ea0','heading','{"level": 2, "text": "Mulk Raj Anand"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a65b44a7560','ch_330096755ea0','text','{"text": "*********"}',40);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_e9a41a5077bd','bk_ncert_english','10-2-the-adventures-of-toto','10.2 The Adventures of Toto',NULL,'public',24,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b2269d0e460','ch_e9a41a5077bd','text','{"text": "GRANDFATHER bought Toto from a tonga-driver for the sum of five rupees. The tonga-driver used to keep the little red monkey tied to a feeding-trough, and the monkey looked so out of place there that Grandfather decided he would add the little fellow to his private zoo. Toto was a pretty monkey."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7778b52e5d44','ch_e9a41a5077bd','text','{"text": "His bright eyes sparkled with mischief beneath deep-set eyebrows, and his teeth, which were a pearly white, were very often displayed in a smile that frightened the life out of elderly Anglo-lndian ladies. But his hands looked dried-up as though they had been pickled in the sun for many years. Yet his fingers were quick and wicked; and his tail, while adding to his good looks (Grandfather believed a tail would add to anyone’s good looks), also served as a third hand."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a44217fed48','ch_e9a41a5077bd','text','{"text": "He could use it to hang from a branch; and it was capable of scooping up any delicacy that might be out of reach of his hands. Grandmother always fussed when Grandfather brought home some new bird or animal. So it was decided that Toto’s presence should be kept a secret from her until she was in a particularly good mood. Grandfather and I put him away in a little closet opening into my bedroom wall, where he was tied securely — or so we thought — to a peg fastened into the wall."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_144415cff005','ch_e9a41a5077bd','text','{"text": "A few hours later, when Grandfather and I came back to release Toto, we found that the walls, which had been covered with some ornamental paper chosen by Grandfather, now stood out as naked brick and plaster. The peg in the wall had been wrenched from its socket, and my school blazer, which had been hanging there, was in shreds. I wondered what Grandmother would say. But Grandfather didn’t worry; he seemed pleased with Toto’s performance."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ace54055b46b','ch_e9a41a5077bd','text','{"text": "‘He’s clever,’ said Grandfather."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc08ce921cb0','ch_e9a41a5077bd','text','{"text": "‘Given time, I’m sure he could have tied the torn pieces of your blazer into a rope, and made his escape from the window!’ His presence in the house still a secret, Toto was now transferred to a big cage in the servants’ quarters where a number of Grandfather’s pets lived very sociably together — a tortoise, a pair of rabbits, a tame squirrel and, for a while, my pet goat."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e2132ae300b','ch_e9a41a5077bd','text','{"text": "But the monkey wouldn’t allow any of his companions to sleep at night; so Grandfather, who had to leave Dehra Dun next day to collect his pension in Saharanpur, decided to take him along. Unfortunately I could not accompany Grandfather on that trip, but he told me about it afterwards. A big black canvas kit-bag was provided for Toto. This, with some straw at the bottom, became his new abode. When the bag was closed, there was no escape."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d534b4d58fd','ch_e9a41a5077bd','text','{"text": "Toto could not get his hands through the opening, and the canvas was too strong for him to bite his way through. His efforts to get out only had the effect of making the bag roll about on the floor or occasionally jump into the air — an exhibition that attracted a curious crowd of onlookers on the Dehra Dun railway platform."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5cab0121608','ch_e9a41a5077bd','text','{"text": "Toto remained in the bag as far as Saharanpur, but while Grandfather was producing his ticket at the railway turnstile, Toto suddenly poked his head out of the bag and gave the ticketcollector a wide grin. The poor man was taken aback; but, with great presence of mind and much to Grandfather’s annoyance, he said, ‘Sir, you have a dog with you. You’ll have to pay for it accordingly.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_864247522a57','ch_e9a41a5077bd','text','{"text": "In vain did Grandfather take Toto out of the bag; in vain did he try to prove that a monkey did not qualify as a dog, or even as a quadruped. Toto was classified a dog by the ticket-collector; and three rupees was the sum handed over as his fare."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f7f62355c6a','ch_e9a41a5077bd','text','{"text": "Then Grandfather, just to get his own back, took from his pocket our pet tortoise, and said, ‘What must I pay for this, since you charge for all animals?’ The ticket-collector looked closely at the tortoise, prodded it with his forefinger, gave Grandfather a pleased and triumphant look, and said, ‘No charge. It is not a dog.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_524f9ff0a19e','ch_e9a41a5077bd','text','{"text": "When Toto was finally accepted by Grandmother he was given a comfortable home in the stable, where he had for a companion the family donkey, Nana. On Toto’s first night in the stable, Grandfather paid him a visit to see if he was comfortable. To his surprise he found Nana, without apparent cause, pulling at her halter and trying to keep her head as far as possible from a bundle of hay. Grandfather gave Nana a slap across her haunches, and she jerked back, dragging Toto with her."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66dca72d6218','ch_e9a41a5077bd','text','{"text": "He had fastened on to her long ears with his sharp little teeth. Toto and Nana never became friends. A great treat for Toto during cold winter evenings was the large bowl of warm water given him by Grandmother for his bath. He would cunningly test the temperature with his hand, then gradually step into the bath, first one foot, then the other (as he had seen me doing), until he was into the water up to his neck."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_991619c0c07a','ch_e9a41a5077bd','text','{"text": "Once comfortable, he would take the soap in his hands or feet, and rub himself all over. When the water became cold, he would get out and run as quickly as he could to the kitchen-fire in order to dry himself. If anyone laughed at him during this performance, Toto’s feelings would be hurt and he would refuse to go on with his bath. One day Toto nearly succeeded in boiling himself alive."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b76fb5095e9','ch_e9a41a5077bd','text','{"text": "A large kitchen kettle had been left on the fire to boil for tea and Toto, finding himself with nothing better to do, decided to remove the lid. Finding the water just warm enough for a bath, he got in, with his head sticking out from the open kettle. This was just fine for a while, until the water began to boil. Toto then raised himself a little; but, finding it cold outside, sat down again."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b16357477b45','ch_e9a41a5077bd','text','{"text": "He continued hopping up and down for some time, until Grandmother arrived and hauled him, half-boiled, out of the kettle. If there is a part of the brain especially devoted to mischief, that part was largely developed in Toto. He was always tearing things to pieces. Whenever one of my aunts came near him, he made every effort to get hold of her dress and tear a hole in it. One day, at lunch-time, a large dish of pullao stood in the centre of the dining-table."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f0a49dc8fc1','ch_e9a41a5077bd','text','{"text": "We entered the room to find Toto stuffing himself with rice. My grandmother screamed — and Toto threw a plate at her. One of my aunts rushed forward — and received a glass of water in the face. When Grandfather arrived, Toto picked up the dish of pullao and made his exit through a window. We found him in the branches of the jackfruit tree, the dish still in his arms. He remained there all afternoon, eating slowly through the rice, determined on finishing every grain."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f23309bff71','ch_e9a41a5077bd','text','{"text": "And then, in order to spite Grandmother, who had screamed at him, he threw the dish down from the tree, and chattered with delight when it broke into a hundred pieces. Obviously Toto was not the sort of pet we could keep for long. Even Grandfather realised that. We were not well-to-do, and could not afford the frequent loss of dishes, clothes, curtains and wallpaper. So Grandfather found the tonga-driver, and sold Toto back to him — for only three rupees."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a31e48959cae','ch_e9a41a5077bd','heading','{"level": 2, "text": "Ruskin Bond"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05e478653a7b','ch_e9a41a5077bd','text','{"text": "*********"}',20);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b8cb1e7c0e47','bk_ncert_english','10-3-iswaran-the-story-teller','10.3 Iswaran the Story Teller',NULL,'public',25,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f7479425785','ch_b8cb1e7c0e47','text','{"text": "Iswaran the Story Teller THE story was narrated to Ganesh by a young man, Mahendra by name. He was a junior supervisor in a firm which offered on hire supervisors at various types of construction sites:"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbce1cd01e1b','ch_b8cb1e7c0e47','text','{"text": "factories, bridges, dams, and so on. Mahendra’s job was to keep an eye on the activities at the work site."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45aefbe43aaf','ch_b8cb1e7c0e47','text','{"text": "He had to keep moving from place to place every now and then as ordered by his head office:"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07d48ef9269f','ch_b8cb1e7c0e47','text','{"text": "from a coal mining area to a railway bridge construction site, from there after a few months to a chemical plant which was coming up somewhere. He was a bachelor. His needs were simple and he was able to adjust himself to all kinds of odd conditions, whether it was an illequipped circuit house or a makeshift canvas tent in the middle of a stone quarry. But one asset he had was his cook, Iswaran."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08b281a81a2b','ch_b8cb1e7c0e47','text','{"text": "The cook was quite attached to Mahendra and followed him uncomplainingly wherever he was posted. He cooked for Mahendra, washed his clothes and chatted away with his master at night. He could weave out endless stories and anecdotes on varied subjects. Iswaran also had an amazing capacity to produce vegetables and cooking ingredients, seemingly out of nowhere, in the middle of a desolate landscape with no shops visible for miles around."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af238f127187','ch_b8cb1e7c0e47','text','{"text": "He would miraculously conjure up the most delicious dishes made with fresh vegetables within an hour of arriving at the zincsheet shelter at the new workplace. Mahendra would be up early in the morning and leave for work after breakfast, carrying some prepared food with him. Meanwhile Iswaran would tidy up the shed, wash the clothes, and have a leisurely bath, pouring several buckets of water over his head, muttering a prayer all the while. It would be lunchtime by then."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52e24449a2fe','ch_b8cb1e7c0e47','text','{"text": "After eating, he would read for a while before dozing off. The book was usually some popular Tamil thriller running to hundreds of pages. Its imaginative descriptions and narrative flourishes would hold Iswaran in thrall. His own descriptions were greatly influenced by the Tamil authors that he read. When he was narrating even the smallest of incidents, he would try to work in suspense and a surprise ending into the account."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55d1377f4e56','ch_b8cb1e7c0e47','text','{"text": "For example, instead of saying that he had come across an uprooted tree on the highway, he would say, with eyebrows suitably arched and hands held out in a dramatic gesture, ‘The road was deserted and I was all alone. Suddenly I spotted something that looked like an enormous bushy beast lying sprawled across the road. I was half inclined to turn and go back. But as I came closer I saw that it was a fallen tree, with its dry branches spread out.’"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfd7597123f1','ch_b8cb1e7c0e47','text','{"text": "Mahendra would stretch himself back in his canvas chair and listen to Iswaran’s tales uncritically."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85f3b5f93d3b','ch_b8cb1e7c0e47','text','{"text": "‘The place I come from is famous for timber,’ Iswaran would begin."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ea24265b8c7','ch_b8cb1e7c0e47','text','{"text": "‘There is a richly wooded forest all around. The logs are hauled on to the lorries by elephants. They are huge wellfed beasts. When they turn wild even the most experienced mahout is not able to control them.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96a87abfdd92','ch_b8cb1e7c0e47','text','{"text": "After this prologue Iswaran would launch into an elaborate anecdote involving an elephant."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_590146ffee44','ch_b8cb1e7c0e47','text','{"text": "‘One day a tusker escaped from the timber yard and began to roam about, stamping on bushes, tearing up wild creepers and breaking branches at will. You know, sir, how an elephant behaves when it goes mad.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ebaedec99a26','ch_b8cb1e7c0e47','text','{"text": "Iswaran would get so caught up in the excitement of his own story that he would get up from the floor and jump about, stamping his feet in emulation of the mad elephant."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_faf5a3ad909a','ch_b8cb1e7c0e47','text','{"text": "‘The elephant reached the outskirts of our town; breaking the fences down like matchsticks,’ he would continue."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa4aa3cf22f5','ch_b8cb1e7c0e47','text','{"text": "‘It came into the main road and smashed all the stalls selling fruits, mud pots and clothes. People ran helterskelter in panic! The elephant now entered a school ground where children were playing, breaking through the brick wall. All the boys ran into the classrooms and shut the doors tight. The beast grunted and wandered about, pulling out the football goalpost, tearing down the volleyball net, kicking and flattening the drum kept for water, and uprooting the shrubs."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82eee62afb4f','ch_b8cb1e7c0e47','text','{"text": "Meanwhile all the teachers had climbed up to the terrace of the school building; from there they helplessly watched the depredations of the elephant. There was not a soul below on the ground. The streets were empty as if the inhabitants of the entire town had suddenly disappeared."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa20d961b83c','ch_b8cb1e7c0e47','text','{"text": "‘I was studying in the junior class at that time, and was watching the whole drama from the rooftop. I don’t know what came over me suddenly. I grabbed a cane from the hands of one of the teachers and ran down the stairs and into the open. The elephant grunted and menacingly swung a branch of a tree which it held in its trunk. It stamped its feet, kicking up a lot of mud and dust. It looked frightening. But I moved slowly towards it, stick in hand."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6ddfb2661d1','ch_b8cb1e7c0e47','text','{"text": "People were watching the scene hypnotised from nearby housetops. The elephant looked at me redeyed, ready to rush towards me. It lifted its trunk and trumpeted loudly. At that moment I moved forward and, mustering all my force, whacked its third toenail on the quick. The beast looked stunned for a moment; then it shivered from head to foot — and collapsed.’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9264a94843d','ch_b8cb1e7c0e47','text','{"text": "At this point Iswaran would leave the story unfinished, and get up mumbling, ‘I will be back after lighting the gas and warming up the dinner.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a893aa70b88','ch_b8cb1e7c0e47','text','{"text": "Mahendra who had been listening with rapt attention would be left hanging. When he returned, Iswaran would not pick up the thread of the story right away. Mahendra would have to remind him that the conclusion was pending."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_494d40aa43a5','ch_b8cb1e7c0e47','text','{"text": "‘Well, a veterinary doctor was summoned to revive the animal,’ Iswaran would shrug casually."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5cdc18e281d5','ch_b8cb1e7c0e47','text','{"text": "‘Two days later it was led away by its mahout to the jungle.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d4c655d3668','ch_b8cb1e7c0e47','text','{"text": "‘Well, how did you manage to do it, Iswaran — how did you bring down the beast?’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00fba58573d5','ch_b8cb1e7c0e47','text','{"text": "‘It has something to do with a Japanese art, I think, sir. Karate or jujitsu it is called. I had read about it somewhere. It temporarily paralyses the nervous system, you see.’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc2991ff53f0','ch_b8cb1e7c0e47','text','{"text": "Not a day passed without Iswaran recounting some story packed with adventure, horror and suspense. Whether the story was credible or not, Mahendra enjoyed listening to it because of the inimitable way in which it was told. Iswaran seemed to more than make up for the absence of a TV in Mahendra’s living quarters."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99b905e68386','ch_b8cb1e7c0e47','text','{"text": "One morning when Mahendra was having breakfast Iswaran asked, ‘Can I make something special for dinner tonight, sir? After all today is an auspicious day — according to tradition we prepare various delicacies to feed the spirits of our ancestors today, sir.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbc9a37058d6','ch_b8cb1e7c0e47','text','{"text": "That night Mahendra enjoyed the most delicious dinner and complimented Iswaran on his culinary skills. He seemed very pleased but, unexpectedly, launched into a most garish account involving the supernatural."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df585560c1b7','ch_b8cb1e7c0e47','text','{"text": "‘You know, sir, this entire factory area we are occupying was once a burial ground,’ he started."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb8b07a9bfe5','ch_b8cb1e7c0e47','text','{"text": "Mahendra was jerked out of the pleasant reverie he had drifted into after the satisfying meal."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1101c043d55','ch_b8cb1e7c0e47','text','{"text": "‘I knew on the first day itself when I saw a human skull lying on the path. Even now I come across a number of skulls and bones,’ Iswaran continued. He went on to narrate how he sometimes saw ghosts at night."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50c8c7754a9f','ch_b8cb1e7c0e47','text','{"text": "‘I am not easily frightened by these things, sir. I am a brave fellow. But one horrible ghost of a woman which appears off and on at midnight during the full moon... It is an ugly creature with matted hair and a shrivelled face, like a skeleton holding a foetus in its arms.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_960f8c065740','ch_b8cb1e7c0e47','text','{"text": "Mahendra shivered at the description and interrupted rather sharply, ‘You are crazy, Iswaran. There are no such things as ghosts or spirits. It is all a figment of your imagination. Get your digestive system examined — and maybe your head as well. You are talking nonsense.’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b0930069623','ch_b8cb1e7c0e47','text','{"text": "He left the room and retired for the night, expecting Iswaran to sulk for a couple of days. But the next morning he was surprised to find the cook as cheerful and talkative as ever. From that day on Mahendra, for all his brave talk, went to bed with a certain unease. Every night he peered into the darkness outside through the window next to his bed, trying to make sure that there was no movement of dark shapes in the vicinity."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_120d42cdab30','ch_b8cb1e7c0e47','text','{"text": "But he could only see a sea of darkness with the twinkling lights of the factory miles away. He had always liked to admire the milkwhite landscape on fullmoon nights. But after hearing Iswaran’s story of the female ghost he avoided looking out of his window altogether when the moon was full. One night, Mahendra was woken up from his sleep by a low moan close to his window. At first he put it down to a cat prowling around for mice. But the sound was too guttural for a cat."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc54a9466f3c','ch_b8cb1e7c0e47','text','{"text": "He resisted the curiosity to look out lest he should behold a sight which would stop his heart. But the wailing became louder and less feline. He could not resist the temptation any more. Lowering himself to the level of the windowsill he looked out at the white sheet of moonlight outside. There, not too far away, was a dark cloudy form clutching a bundle. Mahendra broke into a cold sweat and fell back on the pillow, panting."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91362e82a331','ch_b8cb1e7c0e47','text','{"text": "As he gradually recovered from the ghastly experience he began to reason with himself, and finally concluded that it must have been some sort of auto suggestion, some trick that his subconscious had played on him. By the time he had got up in the morning, had a bath and come out to have his breakfast, the horror of the previous night had faded from his memory. Iswaran greeted him at the door with his lunch packet and his bag."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75950ccfa8bc','ch_b8cb1e7c0e47','text','{"text": "Just as Mahendra was stepping out Iswaran grinned and said, ‘Sir, remember the other day when I was telling you about the female ghost with a foetus in its arms, you were so angry with me for imagining things? Well, you saw her yourself last night. I came running hearing the sound of moaning that was coming from your room...’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4f84d1d7617','ch_b8cb1e7c0e47','text','{"text": "A chill went down Mahendra’s spine. He did not wait for Iswaran to complete his sentence. He hurried away to his office and handed in his papers, resolving to leave the haunted place the very next day!"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67b928b61bbe','ch_b8cb1e7c0e47','heading','{"level": 2, "text": "R.K. Laxman"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec359daa5cff','ch_b8cb1e7c0e47','text','{"text": "*********"}',41);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_2093c2c04f44','bk_ncert_english','10-4-in-the-kingdom-of-fools','10.4 In the Kingdom of Fools',NULL,'public',26,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_644ef536e6e4','ch_2093c2c04f44','text','{"text": "IN the Kingdom of Fools, both the king and the minister were idiots. They didn’t want to run things like other kings, so they decided to change night into day and day into night."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc66416d8c86','ch_2093c2c04f44','text','{"text": "They ordered that everyone should be awake at night, till their fields and run their businesses only after dark, and go to bed as soon as the sun came up. Anyone who disobeyed would be punished with death. The people did as they were told for fear of death. The king and the minister were delighted at the success of their project. One day a guru and his disciple arrived in the city. It was a beautiful city, it was broad daylight, but there was no one about."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6930cbb1393e','ch_2093c2c04f44','text','{"text": "Everyone was asleep, not a mouse stirring. Even the cattle had been taught to sleep by day. The two strangers were amazed by what they saw around them and wandered around town till evening, when suddenly the whole town woke up and went about its nightly business. The two men were hungry. Now that the shops were open, they went to buy some groceries."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e899ebfa625b','ch_2093c2c04f44','text','{"text": "To their astonishment, they found that everything cost the same, a single duddu — whether they bought a measure of rice or a bunch of bananas, it cost a duddu. The guru and his disciple were delighted. They had never heard of anything like this. They could buy all the food they wanted for a rupee. When they had cooked and eaten, the guru realised that this was a kingdom of fools and it wouldn’t be a good idea for them to stay there."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07eb669092d9','ch_2093c2c04f44','text','{"text": "‘This is no place for us. Let’s go,’ he said to his disciple. But the disciple didn’t want to leave the place. Everything was cheap here. All he wanted was good, cheap food. The guru said, ‘They are all fools. This won’t last very long, and you can’t tell what they’ll do to you next.’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7ff130d4f18','ch_2093c2c04f44','text','{"text": "But the disciple wouldn’t listen to the guru’s wisdom. He wanted to stay. The guru finally gave up and said, ‘Do what you want. I’m going,’ and left. The disciple stayed on, ate his fill every day — bananas and ghee and rice and wheat, and grew fat like a street-side sacred bull. One bright day, a thief broke into a rich merchant’s house. He had made a hole in the wall and sneaked in, and as he was carrying out his loot, the wall of the old house collapsed on his head and killed him on the spot."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b18e752a0ee7','ch_2093c2c04f44','text','{"text": "His brother ran to the king and complained, ‘Your Highness, when my brother was pursuing his ancient trade, a wall fell on him and killed him. This merchant is to blame. He should have built a good, strong wall. You must punish the wrongdoer and compensate the family for this injustice.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df03c658f49a','ch_2093c2c04f44','text','{"text": "The king said, ‘Justice will be done. Don’t worry,’ and at once summoned the owner of the house. When the merchant arrived, the king questioned him."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12b43cd48fd5','ch_2093c2c04f44','text','{"text": "‘What’s your name?’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1de65d039d3','ch_2093c2c04f44','text','{"text": "‘Such and Such, Your Highness.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efd1ec434647','ch_2093c2c04f44','text','{"text": "‘Were you at home when the dead man burgled your house?’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b3857df51c0','ch_2093c2c04f44','text','{"text": "‘Yes, My Lord. He broke in and the wall was weak. It fell on him.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f744e4dfee12','ch_2093c2c04f44','text','{"text": "‘The accused pleads guilty. Your wall killed this man’s brother. You have murdered a man. We have to punish you.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d5d8a8c4242','ch_2093c2c04f44','text','{"text": "‘Lord,’ said the helpless merchant, ‘I didn’t put up the wall. It’s really the fault of the man who built the wall. He didn’t build it right. You should punish him.’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45fe4d9d4b17','ch_2093c2c04f44','text','{"text": "‘Who is that?’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad92864088e0','ch_2093c2c04f44','text','{"text": "‘My Lord, this wall was built in my father’s time."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd233782f4b9','ch_2093c2c04f44','text','{"text": "I know the man. He’s an old man now. He lives nearby.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e044253cc859','ch_2093c2c04f44','text','{"text": "The king sent out messengers to bring in the bricklayer who had built the wall. They brought him, tied hand and foot."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01094f1dce96','ch_2093c2c04f44','text','{"text": "‘You there, did you build this man’s wall in his father’s time?’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c50695c1ec6','ch_2093c2c04f44','text','{"text": "‘Yes, My Lord, I did.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f9e3ca24ad3','ch_2093c2c04f44','text','{"text": "‘What kind of a wall is this that you built? It has fallen on a poor man and killed him. You’ve murdered him. We have to punish you by death.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49e3b10a05e0','ch_2093c2c04f44','text','{"text": "Before the king could order the execution, the poor bricklayer pleaded, ‘Please listen to me before you give your orders. It’s true I built this wall and it was no good. But that was because my mind was not on it. I remember very well a dancing girl who was going up and down that street all day with her anklets jingling, and I couldn’t keep my eyes or my mind on the wall I was building. You must get that dancing girl. I know where she lives.’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_549492bf1e55','ch_2093c2c04f44','text','{"text": "‘You’re right. The case deepens. We must look into it. It is not easy to judge such complicated cases. Let’s get that dancer, wherever she is.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_548c41bbfac6','ch_2093c2c04f44','text','{"text": "The dancing girl, now an old woman, came trembling to the court."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e345f6a11e46','ch_2093c2c04f44','text','{"text": "‘Did you walk up and down that street many years ago, while this poor man was building a wall? Did you see him?’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3af03c7a3c8c','ch_2093c2c04f44','text','{"text": "‘Yes, My Lord, I remember it very well.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e732b169d65d','ch_2093c2c04f44','text','{"text": "‘So you did walk up and down, with your anklets jingling. You were young and you distracted him, so he built a bad wall. It has fallen on a poor burglar and killed him. You’ve killed an innocent man. You’ll have to be punished.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86b6c021d6a1','ch_2093c2c04f44','text','{"text": "She thought for a minute and said, ‘My Lord, wait. I know now why I was walking up and down that street. I had given some gold to the goldsmith to make some jewellery for me. He was a lazy scoundrel. He made so many excuses, said he would give it now and he would give it then and so on all day. He made me walk up and down to his house a dozen times. That was when this bricklayer saw me. It’s not my fault, My Lord, it’s the damned goldsmith’s fault.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92c13690e50f','ch_2093c2c04f44','text','{"text": "‘Poor thing, she’s absolutely right,’ thought the king, weighing the evidence."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70803fec2962','ch_2093c2c04f44','text','{"text": "‘We’ve got the real culprit at last. Get the goldsmith, wherever he is hiding. At once!’ The king’s bailiffs searched for the goldsmith, who was hiding in a corner of his shop. When he heard the accusation against him, he had his own story to tell."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83605b2fc508','ch_2093c2c04f44','text','{"text": "‘My Lord,’ he said, ‘I’m a poor goldsmith."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f634f8c2c51','ch_2093c2c04f44','text','{"text": "It’s true I made this dancer come many times to my door. I gave her excuses because I couldn’t finish making her jewellery before I finished the rich merchant’s orders. They had a wedding coming, and they wouldn’t wait. You know how impatient rich men are!’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_487866394fec','ch_2093c2c04f44','text','{"text": "‘Who is this rich merchant who kept you from finishing this poor woman’s jewellery, made her walk up and down, which distracted this bricklayer, which made a mess of his wall, which has now fallen on an innocent man and killed him? Can you name him?’ The goldsmith named the merchant, and he was none other than the original owner of the house whose wall had fallen."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8664be00685','ch_2093c2c04f44','text','{"text": "Now justice had come full circle, thought the king, back to the merchant. When he was rudely summoned back to the court, he arrived crying, ‘It wasn’t me but my father who ordered the jewellery! He’s dead! I’m innocent!’ But the king consulted his minister and ruled decisively:"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_628b70b8ad5a','ch_2093c2c04f44','text','{"text": "‘It’s true your father is the true murderer. He’s dead, but somebody must be punished in his place. You’ve inherited everything from that criminal father of yours, his riches as well as his sins. I knew at once, even when I first set eyes on you, that you were at the root of this horrible crime. You must die.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ea15547c190','ch_2093c2c04f44','text','{"text": "And he ordered a new stake to be made ready for the execution. As the servants sharpened the stake and got it ready for the final impaling of the criminal, it occurred to the minister that the rich merchant was somehow too thin to be properly executed on the stake. He appealed to the king’s common sense. The king too worried about it."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fe48bacbcd7','ch_2093c2c04f44','text','{"text": "‘What shall we do?’ he said, when suddenly it struck him that all they needed to do was to find a man fat enough to fit the stake."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37fd31d9aea7','ch_2093c2c04f44','text','{"text": "The servants were immediately sent all over the town looking for a man who would fit the stake, and their eyes fell on the disciple who had fattened himself for months on bananas and rice and wheat and ghee."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbce7e88c471','ch_2093c2c04f44','text','{"text": "‘What have I done wrong? I’m innocent."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c07a63764af','ch_2093c2c04f44','text','{"text": "I’m a sanyasi!’ he cried."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de79d9585412','ch_2093c2c04f44','text','{"text": "‘That may be true. But it’s the royal decree that we should find a man fat enough to fit the stake,’ they said, and carried him to the place of execution. He remembered his wise guru’s words:"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59c127c5fe09','ch_2093c2c04f44','text','{"text": "‘This is a city of fools. You don’t know what they will do next.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a98dc843f587','ch_2093c2c04f44','text','{"text": "While he was waiting for death, he prayed to his guru in his heart, asking him to hear his cry wherever he was. The guru saw everything in a vision; he had magic powers, he could see far, and he could see the future as he could see the present and the past. He arrived at once to save his disciple, who had got himself into such a scrape through love of food. As soon as he arrived, he scolded the disciple and told him something in a whisper."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4308f3e4e86c','ch_2093c2c04f44','text','{"text": "Then he went to the king and addressed him, ‘O wisest of kings, who is greater? The guru or the disciple?’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94225a7b45eb','ch_2093c2c04f44','text','{"text": "‘Of course, the guru. No doubt about it. Why do you ask?’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee89614fab74','ch_2093c2c04f44','text','{"text": "‘Then put me to the stake first. Put my disciple to death after me.’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b734930c5f15','ch_2093c2c04f44','text','{"text": "When the disciple heard this, he understood and began to clamour, ‘Me first! You brought me here first! Put me to death first, not him!’ The guru and the disciple now got into a fight about who should go first. The king was puzzled by this behaviour. He asked the guru, ‘Why do you want to die? We chose him because we needed a fat man for the stake.’"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eacbe6c3be12','ch_2093c2c04f44','text','{"text": "‘You shouldn’t ask me such questions."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f98e42210cf','ch_2093c2c04f44','text','{"text": "Put me to death first,’ replied the guru."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e69c0697684b','ch_2093c2c04f44','text','{"text": "‘Why? There’s some mystery here."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_605459acf86e','ch_2093c2c04f44','text','{"text": "As a wise man you must make me understand.’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0e81c92214d','ch_2093c2c04f44','text','{"text": "‘Will you promise to put me to death if I tell you?’ asked the guru."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93d26c9d4e32','ch_2093c2c04f44','text','{"text": "The king gave him his solemn word. The guru took him aside, out of the servants’ earshot, and whispered to him, ‘Do you know why we want to die right now, the two of us? We’ve been all over the world but we’ve never found a city like this or a king like you. That stake is the stake of the god of justice. It’s new, it has never had a criminal on it. Whoever dies on it first will be reborn as the king of this country. And whoever goes next will be the future minister of this country."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56ed7581d5d7','ch_2093c2c04f44','text','{"text": "We’re sick of our ascetic life. It would be nice to enjoy ourselves as king and minister for a while. Now keep your word, My Lord, and put us to death. Me first, remember?’ The king was now thrown into deep thought. He didn’t want to lose the kingdom to someone else in the next round of life. He needed time. So he ordered the execution postponed to the next day and talked in secret with his minister."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50e7a0dbffb1','ch_2093c2c04f44','text','{"text": "‘It’s not right for us to give over the kingdom to others in the next life. Let’s go on the stake ourselves and we’ll be reborn as king and minister again. Holy men do not tell lies,’ he said, and the minister agreed. So he told the executioners, ‘We’ll send the criminals tonight. When the first man comes to you, put him to death first. Then do the same to the second man. Those are my orders. Don’t make any mistake.’"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b76f70d577e4','ch_2093c2c04f44','text','{"text": "That night, the king and his minister went secretly to the prison, released the guru and the disciple, disguised themselves as the two, and as arranged beforehand with loyal servants, were taken to the stake and promptly executed. When the bodies were taken down to be thrown to crows and vultures the people panicked. They saw before them the dead bodies of the king and the minister. The city was in confusion. All night they mourned and discussed the future of the kingdom."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3cde2971968c','ch_2093c2c04f44','text','{"text": "Some people suddenly thought of the guru and the disciple and caught up with them as they were preparing to leave town unnoticed."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33a5d3fc7624','ch_2093c2c04f44','text','{"text": "‘We people need a king and a minister,’ said someone."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4d56727eae5','ch_2093c2c04f44','text','{"text": "Others agreed. They begged the guru and the disciple to be their king and their minister. It didn’t take many arguments to persuade the disciple, but it took longer to persuade the guru. They finally agreed to rule the kingdom of the foolish king and the silly minister, on the condition that they could change all the old laws. From then on, night would again be night and day would again be day, and you could get nothing for a duddu. It became like any other place."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26309e0ca686','ch_2093c2c04f44','text','{"text": "[A Kannada folktale from A.K. Ramanujan’s Folk Tales from India]"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5158f008c531','ch_2093c2c04f44','text','{"text": "*********"}',61);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_4c193414be09','bk_ncert_english','10-5-the-happy-prince','10.5 The Happy Prince',NULL,'public',27,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f85790132ac3','ch_4c193414be09','text','{"text": "HIGH above the city, on a tall column, stood the statue of the Happy Prince. He was gilded all over with thin leaves of fine gold, for eyes he had two bright sapphires, and a large red ruby glowed on his sword hilt. One night there flew over the city a little swallow. His friends had gone away to Egypt six weeks before, but he had stayed behind; then he decided to go to Egypt too."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb33f23db998','ch_4c193414be09','text','{"text": "All day long he flew, and at night time he arrived at the city."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0fc7325b80d','ch_4c193414be09','text','{"text": "‘Where shall I put up?’ he said."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bacf6186dfc1','ch_4c193414be09','text','{"text": "‘I hope the town has made preparations.’"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c6be0517daf','ch_4c193414be09','text','{"text": "Then he saw the statue on the tall column."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a75473c035a2','ch_4c193414be09','text','{"text": "‘I will put up there,’ he cried."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3102ba375289','ch_4c193414be09','text','{"text": "‘It is a fine position with plenty of fresh air.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4b8f53e9f71','ch_4c193414be09','text','{"text": "So he alighted just between the feet of the Happy Prince."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22f41feb7178','ch_4c193414be09','text','{"text": "‘I have a golden bed-room,’ he said softly to himself as he looked round, and he prepared to go to sleep; but just as he was putting his head under his wing a large drop of water fell on him."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_813ca2f53725','ch_4c193414be09','text','{"text": "‘What a curious thing!’ he cried."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57425e3c7785','ch_4c193414be09','text','{"text": "‘There is not a single cloud in the sky, the stars are quite clear and bright, and yet it is raining.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f98c50b3cd3','ch_4c193414be09','text','{"text": "Then another drop fell."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc33a2983b5e','ch_4c193414be09','text','{"text": "‘What is the use of a statue if it cannot keep the rain off ?’ he said."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bcd2a17c6b6','ch_4c193414be09','text','{"text": "‘I must look for a good chimney pot,’ and he determined to fly away."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7a28cd5b9c1','ch_4c193414be09','text','{"text": "But before he had opened his wings, a third drop fell, and he looked up, and saw — Ah! What did he see? The eyes of the Happy Prince were filled with tears, and tears were running down his golden cheeks. His face was so beautiful in the moonlight that the little swallow was filled with pity."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b90da616b368','ch_4c193414be09','text','{"text": "‘Who are you?’ he said."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65e1268a1861','ch_4c193414be09','text','{"text": "‘I am the Happy Prince.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca3bf2629f34','ch_4c193414be09','text','{"text": "‘Why are you weeping then?’ asked the swallow."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c9a272f3bfe','ch_4c193414be09','text','{"text": "‘You have quite drenched me.’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f56799b06150','ch_4c193414be09','text','{"text": "‘When I was alive and had a human heart,’ answered the statue, ‘I did not know what tears were, for I lived in the Palace, where sorrow is not allowed to enter."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17fa53cde5c9','ch_4c193414be09','text','{"text": "My courtiers called me the Happy Prince, and happy indeed I was. So I lived, and so I died. And now that I am dead they have set me up here so high that I can see the ugliness and all the misery of my city, and though my heart is made of lead yet I cannot choose but weep.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bca96ec7337d','ch_4c193414be09','text','{"text": "‘What! Is he not solid gold?’ said the swallow to himself."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a67b2d128a0d','ch_4c193414be09','text','{"text": "He was too polite to make any personal remarks."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a0176033181','ch_4c193414be09','text','{"text": "‘Far away,’ continued the statue in a low musical voice, ‘far away in a little street there is a poor house."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b206b2935421','ch_4c193414be09','text','{"text": "One of the windows is open, and through it I can see a woman seated at a table. Her face is thin and worn, and she has coarse, red hands, all pricked by the needle, for she is a seamstress. She is embroidering flowers on a satin gown for the loveliest of the Queen’s maids of honour, to wear at the next Court ball. In a bed in the corner of the room her little boy is lying ill. He has a fever, and is asking his mother to give him oranges."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fedebc728dd','ch_4c193414be09','text','{"text": "His mother has nothing to give him but river water, so he is crying. Swallow, Swallow, little Swallow, will you not bring her the ruby out of my sword hilt? My feet are fastened to this pedestal and I cannot move.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_409f65e18233','ch_4c193414be09','text','{"text": "‘I am waited for in Egypt,’ said the swallow."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffaa819537f3','ch_4c193414be09','text','{"text": "‘My friends are flying up and down the Nile, and talking to the large lotus flowers. Soon they will go to sleep.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a45791a63a5c','ch_4c193414be09','text','{"text": "The Prince asked the swallow to stay with him for one night and be his messenger."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_616408e28d7b','ch_4c193414be09','text','{"text": "‘The boy is so thirsty, and the mother so sad,’ he said."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51e6989fa12a','ch_4c193414be09','text','{"text": "‘I don’t think I like boys,’ answered the swallow."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4dbeed2a1c35','ch_4c193414be09','text','{"text": "‘I want to go to Egypt.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_454b91ff42dd','ch_4c193414be09','text','{"text": "But the Happy Prince looked so sad that the little swallow was sorry."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6806628ca2a','ch_4c193414be09','text','{"text": "‘It is very cold here,’ he said."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_664b26cc3f85','ch_4c193414be09','text','{"text": "But he agreed to stay with him for one night and be his messenger."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f97699c7d0e','ch_4c193414be09','text','{"text": "‘Thank you, little Swallow,’ said the Prince."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e5563a9f3e8','ch_4c193414be09','text','{"text": "The swallow picked out the great ruby from the Prince’s sword, and flew away with it in his beak over the roofs of the town. He passed by the cathedral tower, where the white marble angels were sculptured. He passed by the palace and heard the sound of dancing. A beautiful girl came out on the balcony with her lover."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cf7320adaf3','ch_4c193414be09','text','{"text": "‘I hope my dress will be ready in time for the State ball,’ she said."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a3a7ef29fa8','ch_4c193414be09','text','{"text": "‘I have ordered flowers to be embroidered on it, but the seamstresses are so lazy.’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8139836f22d2','ch_4c193414be09','text','{"text": "He passed over the river, and saw the lanterns hanging on the masts of the ships. At last he came to the poor woman’s house and looked in. The boy was tossing feverishly on his bed, and the mother had fallen asleep, she was so tired. In he hopped, and laid the great ruby on the table beside the woman’s thimble. Then he flew gently round the bed, fanning the boy’s forehead with his wings."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2fe4e6c17a53','ch_4c193414be09','text','{"text": "‘How cool I feel!’ said the boy, ‘I must be getting better;’ and he sank into a delicious slumber."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae71512a81da','ch_4c193414be09','text','{"text": "Then the swallow flew back to the Happy Prince, and told him what he had done."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d64dec3912b4','ch_4c193414be09','text','{"text": "‘It is curious,’ he remarked, ‘but I feel quite warm now, although it is so cold.’"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b48fac53971','ch_4c193414be09','text','{"text": "‘That is because you have done a good action,’ said the Prince."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_883c2cd866ac','ch_4c193414be09','text','{"text": "And the little swallow began to think, and then fell asleep. Thinking always made him sleepy. When day broke he flew down to the river and had a bath."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e98e43e818a','ch_4c193414be09','text','{"text": "‘Tonight I go to Egypt,’ said the swallow, and he was in high spirits at the prospect."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b712d3cd0d82','ch_4c193414be09','text','{"text": "He visited all the monuments and sat a long time on top of the church steeple. When the moon rose he flew back to the Happy Prince."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c60baac77df6','ch_4c193414be09','text','{"text": "‘Have you any commissions for Egypt?’ he cried."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b63cfaf4698c','ch_4c193414be09','text','{"text": "‘I am just starting.’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c74f0cd50f17','ch_4c193414be09','text','{"text": "‘Swallow, Swallow, little Swallow,’ said the Prince, ‘will you stay with me one night longer?’"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_662abb12e13d','ch_4c193414be09','text','{"text": "‘I am waited for in Egypt,’ answered the swallow."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7b769fb2f36','ch_4c193414be09','text','{"text": "‘Swallow, Swallow, little Swallow,’ said the Prince, ‘far away across the city I see a young man in a garret."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc4116f157a3','ch_4c193414be09','text','{"text": "He is leaning over a desk covered with papers, and in the glass by his side there is a bunch of withered violets. His hair is brown and crisp, and his lips are red as a pomegranate, and he has large and dreamy eyes. He is trying to finish a play for the Director of the Theatre, but he is too cold to write any more. There is no fire in the grate, and hunger has made him faint.’"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_215362b1c6f0','ch_4c193414be09','text','{"text": "‘I will wait with you one night longer,’ said the swallow, who really had a good heart."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f3c84810366','ch_4c193414be09','text','{"text": "He asked if he should take another ruby to the young playwright."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfde43428265','ch_4c193414be09','text','{"text": "‘Alas! I have no ruby now,’ said the Prince."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b184731f6ab','ch_4c193414be09','text','{"text": "‘My eyes are all that I have left. They are made of rare sapphires, which were brought out of India a thousand years ago.’"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ebf0a03584e','ch_4c193414be09','text','{"text": "He ordered the swallow to pluck out one of them and take it to the playwright."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e75db682c445','ch_4c193414be09','text','{"text": "‘He will sell it to the jeweller, and buy firewood, and finish his play,’ he said."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f3e63f1810f','ch_4c193414be09','text','{"text": "‘Dear Prince,’ said the swallow, ‘I cannot do that,’ and he began to weep."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7789aa4405c4','ch_4c193414be09','text','{"text": "‘Swallow, Swallow, little Swallow,’ said the Prince, ‘do as I command you.’"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_800908cd15e3','ch_4c193414be09','text','{"text": "So the swallow plucked out the Prince’s eye, and flew away to the young man’s garret. It was easy enough to get in, as there was a hole in the roof. Through this he darted, and came into the room. The young man had his head buried in his hands, so he did not hear the flutter of the bird’s wings, and when he looked up he found the beautiful sapphire lying on the withered violets."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ea4cdb43c73','ch_4c193414be09','text','{"text": "‘I am beginning to be appreciated,’ he cried."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f27131388706','ch_4c193414be09','text','{"text": "‘This is from some great admirer. Now I can finish my play,’ and he looked quite happy. The next day the swallow flew down to the harbour. He sat on the mast of a large vessel and watched the sailors working."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7892f5b75506','ch_4c193414be09','text','{"text": "‘I am going to Egypt,’ cried the swallow, but nobody minded, and when the moon rose he flew back to the Happy Prince."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7cfd6e46c4a','ch_4c193414be09','text','{"text": "‘I have come to bid you goodbye,’ he cried."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1eaaa855e37','ch_4c193414be09','text','{"text": "‘Swallow, Swallow, little Swallow,’ said the Prince, ‘will you not stay with me one night longer?’"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38144b36857a','ch_4c193414be09','text','{"text": "‘It is winter,’ answered the swallow, ‘and the snow will soon be here."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b680f047e60e','ch_4c193414be09','text','{"text": "In Egypt the sun is warm on the green palm trees, and the crocodiles lie in the mud and look lazily about them.’"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38c226e9d7d5','ch_4c193414be09','text','{"text": "‘In the square below,’ said the Happy Prince, ‘there stands a little matchgirl."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6bcaaa13404','ch_4c193414be09','text','{"text": "She has let her matches fall in the gutter, and they are all spoiled. Her father will beat her if she does not bring home some money, and she is crying. She has no shoes or stockings, and her little head is bare. Pluck out my other eye, and give it to her, and her father will not beat her.’"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad35c149217e','ch_4c193414be09','text','{"text": "‘I will stay with you one night longer,’ said the swallow, ‘but I cannot pluck out your eye."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40ab06608934','ch_4c193414be09','text','{"text": "You would be quite blind then.’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d01889957782','ch_4c193414be09','text','{"text": "‘Swallow, Swallow, little Swallow,’ said the Prince, ‘do as I command you.’"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd7f8ecb1b6b','ch_4c193414be09','text','{"text": "So he plucked out the Prince’s other eye, and darted down with it. He swooped past the matchgirl, and slipped the jewel into the palm of her hand."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92424d11c2f6','ch_4c193414be09','text','{"text": "‘What a lovely bit of glass!’ cried the little girl; and she ran home, laughing."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f06878615c5','ch_4c193414be09','text','{"text": "Then the swallow came back to the Prince."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eed4010d5f2f','ch_4c193414be09','text','{"text": "‘You are blind now,’ he said, ‘so I will stay with you always.’"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d81cb7f26ce','ch_4c193414be09','text','{"text": "‘No, little Swallow,’ said the poor Prince, ‘you must go away to Egypt.’"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_831cb642558a','ch_4c193414be09','text','{"text": "‘No, I will stay with you always,’ said the swallow, and he slept at the Prince’s feet."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_302807c2b775','ch_4c193414be09','text','{"text": "All the next day he sat on the Prince’s shoulder, and told him stories of what he had seen in strange lands."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf77fe772837','ch_4c193414be09','text','{"text": "‘Dear little Swallow,’ said the Prince, ‘you tell me of marvellous things, but more marvellous than anything is the suffering of men and women."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_612f8659e3de','ch_4c193414be09','text','{"text": "There is no Mystery so great as Misery. Fly over my city, little Swallow, and tell me what you see there.’"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5636459564b2','ch_4c193414be09','text','{"text": "So the swallow flew over the great city, and saw the rich making merry in their beautiful houses, while the beggars were sitting at the gates. He flew into dark lanes, and saw the white faces of starving children looking out listlessly at the black streets. Under the archway of a bridge two little boys were lying in each other’s arms to try and keep themselves warm."}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_517ca07142cb','ch_4c193414be09','text','{"text": "‘How hungry we are!’ they said."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f99c93559497','ch_4c193414be09','text','{"text": "‘You must not lie here,’ shouted the watchman, and they wandered out into the rain."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_955057e211ff','ch_4c193414be09','text','{"text": "Then he flew back and told the Prince what he had seen."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82d9e6ff4ffc','ch_4c193414be09','text','{"text": "‘I am covered with fine gold,’ said the Prince."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27014e455e27','ch_4c193414be09','text','{"text": "‘You must take it off, leaf by leaf, and give it to the poor; the living always think that gold can make them happy.’"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7eabc7436567','ch_4c193414be09','text','{"text": "Leaf after leaf of the fine gold the swallow picked of f, till the Happy Prince looked quite dull and grey. Leaf after leaf of the fine gold he brought to the poor, and the children’s faces grew rosier, and they laughed and played in the street."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0a7fbd5be3f','ch_4c193414be09','text','{"text": "‘We have bread now!’ they cried."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa3156d2a56c','ch_4c193414be09','text','{"text": "Then the snow came, and after the snow came the frost. The streets looked as if they were made of silver. Everybody went about in furs, and the little boys wore scarlet caps and skated on the ice. The poor little swallow grew colder and colder, but he would not leave the Prince, he loved him too well. He picked up crumbs outside the baker’s door when the baker was not looking, and tried to keep himself warm by flapping his wings. But at last he knew that he was going to die."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb09d9a22418','ch_4c193414be09','text','{"text": "He had just enough strength to fly up to the Prince’s shoulder once more."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b15d4ff8934','ch_4c193414be09','text','{"text": "‘Goodbye, dear Prince!’ he murmured."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb9046e71736','ch_4c193414be09','text','{"text": "‘Will you let me kiss your hand?"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdbea1585fe6','ch_4c193414be09','text','{"text": "‘I am glad that you are going to Egypt at last, little Swallow,’ said the Prince."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4dba4919f935','ch_4c193414be09','text','{"text": "‘You have stayed too long here but you must kiss me on the lips, for I love you.’"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d346221932c0','ch_4c193414be09','text','{"text": "‘It is not to Egypt that I am going,’ said the swallow."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44e49da5a9a6','ch_4c193414be09','text','{"text": "‘I am going to the House of Death. Death is the brother of Sleep, is he not?’ And he kissed the Happy Prince on the lips, and fell down dead at his feet. At that moment a curious crack sounded inside the statue, as if something had broken. The fact is that the leaden heart had snapped right in two. It certainly was a dreadfully hard frost. Early the next morning the Mayor was walking in the square below in company with the Town Councillors. As they passed the column he looked up at the statue."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_343231d89caf','ch_4c193414be09','text','{"text": "‘Dear me! How shabby the Happy Prince looks!’ he said."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b136dcf12e2','ch_4c193414be09','text','{"text": "‘How shabby, indeed!’ cried the Town Councillors, who always agreed with the Mayor and they went up to look at it."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e603491e5765','ch_4c193414be09','text','{"text": "‘The ruby has fallen out of his sword, his eyes are gone, and he is golden no longer,’ said the Mayor."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b1d9b4f26b7','ch_4c193414be09','text','{"text": "‘In fact, he is little better than a beggar!’"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdcc9d57bff2','ch_4c193414be09','text','{"text": "‘Little better than a beggar,’ said the Town Councillors."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cba0a4ed1b7e','ch_4c193414be09','text','{"text": "‘And here is actually a dead bird at his feet!’ continued the Mayor."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc6c78da0966','ch_4c193414be09','text','{"text": "‘We must really issue a proclamation that birds are not to be allowed to die here.’"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80d1546f226f','ch_4c193414be09','text','{"text": "And the Town Clerk made a note of the suggestion. So they pulled down the statue of the Happy Prince."}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8af41069c98','ch_4c193414be09','text','{"text": "‘As he is no longer beautiful he is no longer useful,’ said the Art Professor at the University."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2a9f18fa6e6','ch_4c193414be09','text','{"text": "Then they melted the statue in a furnace."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f843fef84342','ch_4c193414be09','text','{"text": "‘What a strange thing!’ said the overseer of the workmen at the foundry."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61a18ad816b6','ch_4c193414be09','text','{"text": "‘This broken lead heart will not melt in the furnace. We must throw it away.’"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6626a2902ee','ch_4c193414be09','text','{"text": "So they threw it on a dust heap where the dead swallow was also lying."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4d8f1dc3003','ch_4c193414be09','text','{"text": "‘Bring me the two most precious things in the city,’ said God to one of His Angels; and the Angel brought Him the leaden heart and the dead bird."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85fa8bf05d14','ch_4c193414be09','text','{"text": "‘You have rightly chosen,’ said God, ‘for in my garden of Paradise this little bird shall sing for ever more and in my city of gold the Happy Prince shall praise me.’"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18bd75f7b644','ch_4c193414be09','heading','{"level": 2, "text": "Oscar Wilde"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b4590beab88','ch_4c193414be09','text','{"text": "*********"}',116);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_3ea2a94bda20','bk_ncert_english','10-6-weathering-the-storm-in-ersama','10.6  Weathering The Storm in Ersama',NULL,'public',28,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3d71f25a539','ch_3ea2a94bda20','text','{"text": "ON 27 October 1999, seven years after his mother’s death, Prashant had gone to the block headquarters of Ersama, a small town in coastal Orissa, some eighteen kilometres from his village, to spend the day with a friend. In the evening, a dark and menacing storm quickly gathered. Winds beat against the houses with a speed and fury that Prashant had never witnessed before."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e14f99182269','ch_3ea2a94bda20','text','{"text": "Heavy and incessant rain filled the darkness, ancient trees were uprooted and crashed to the earth. Screams rent the air as people and houses were swiftly washed away. The angry waters swirled into his friend’s house, neck deep. The building was of brick and mortar and was strong enough to survive the devastation of the wind’s velocity of 350 km per hour."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50db5d1b1227','ch_3ea2a94bda20','text','{"text": "But the cold terror of the family grew with the crashing of trees that had got uprooted and fallen on their house, some time in the middle of the night, damaging its roof and walls. The crazed destruction wrought by the cyclone and the surge of the ocean continued for the next thirty-six hours, although wind speeds had reduced somewhat by the next morning. To escape the waters rising in the house, Prashant and his friend’s family had taken refuge on the roof."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83a1d7e0cb7e','ch_3ea2a94bda20','text','{"text": "Prashant will never forget the shock he experienced at his first glimpse of the devastation wrought by the super cyclone, in the grey light of the early morning. A raging, deadly, brown sheet of water covered everything as far as the eye could see; only fractured cement houses still stood in a few places. Bloated animal carcasses and human corpses floated in every direction. All round even huge old trees had fallen. Two coconut trees had fallen on the roof of their house."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48b5aa58eaa6','ch_3ea2a94bda20','text','{"text": "This was a blessing in disguise, because the tender coconuts from the trees kept the trapped family from starving in the several days that followed. For the next two days, Prashant sat huddled with his friend’s family in the open on the rooftop. They froze in the cold and incessant rain; the rain water washed away Prashant’s tears. The only thought that flashed through his mind was whether his family had survived the fury of the super cyclone."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_866bc3c3e20f','ch_3ea2a94bda20','text','{"text": "Was he to be bereaved once again? Two days later, which seemed to Prashant like two years, the rain ceased and the rain waters slowly began to recede. Prashant was determined to seek out his family without further delay. But the situation was still dangerous, and his friend’s family pleaded with Prashant to stay back a little while longer. But Prashant knew he had to go."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de2a6db7badd','ch_3ea2a94bda20','text','{"text": "He equipped himself with a long, sturdy stick, and then started on his eighteen-kilometre expedition back to his village through the swollen flood waters. It was a journey he would never forget. He constantly had to use his stick to locate the road, to determine where the water was most shallow. At places it was waist deep, and progress was slow. At several points, he lost the road and had to swim."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_060db9361b72','ch_3ea2a94bda20','text','{"text": "After some distance, he was relieved to find two friends of his uncle who were also returning to their village. They decided to move ahead together. As they waded through the waters, the scenes they witnessed grew more and more macabre. They had to push away many human bodies — men, women, children — and carcasses of dogs, goats and cattle that the current swept against them as they moved ahead. In every village that they passed, they could barely see a house standing."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f57949eb9f45','ch_3ea2a94bda20','text','{"text": "Prashant now wept out loud and long. He was sure that his family could not have survived this catastrophe. Eventually, Prashant reached his village, Kalikuda. His heart went cold. Where their home once stood, there were only remnants of its roof. Some of their belongings were caught, mangled and twisted in the branches of trees just visible above the dark waters. Young Prashant decided to go to the Red Cross shelter to look for his family."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_560d17c60a38','ch_3ea2a94bda20','text','{"text": "Among the first people he saw in the crowd was his maternal grandmother. Weak with hunger, she rushed to him, her hands outstretched, her eyes brimming. It was a miracle. They had long given him up for dead. Quickly word spread and his extended family gathered around him, and hugged him tight in relief. Prashant anxiously scanned the motley, battered group. His brother and sister, his uncles and aunts, they all seemed to be there."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa821b9e4be0','ch_3ea2a94bda20','text','{"text": "By the next morning, as he took in the desperate situation in the shelter, he decided to get a grip over himself. He sensed a deathly grief settling upon the 2500 strong crowd in the shelter. Eighty-six lives were lost in the village. All the ninety-six houses had been washed away. It was their fourth day at the shelter. So far they had survived on green coconuts, but there were too few to go around such a tumult of people."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_925105b87a4f','ch_3ea2a94bda20','text','{"text": "Prashant, all of nineteen years, decided to step in as leader of his village, if no one else did. He organised a group of youths and elders to jointly pressurise the merchant once again to part with his rice. This time the delegation succeeded and returned triumphantly, wading through the receding waters with food for the entire shelter. No one cared that the rice was already rotting. Branches from fallen trees were gathered to light a reluctant and slow fire, on which to cook the rice."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_964a54a4975a','ch_3ea2a94bda20','text','{"text": "For the first time in four days, the survivors at the cyclone shelter were able to fill their bellies. His next task was to organise a team of youth volunteers to clean the shelter of filth, urine, vomit and floating carcasses, and to tend to the wounds and fractures of the many who had been injured. On the fifth day, a military helicopter flew over the shelter and dropped some food parcels. It then did not return. The youth task force gathered empty utensils from the shelter."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bd488c1ff41','ch_3ea2a94bda20','text','{"text": "Then they deputed the children to lie in the sand left by the waters around the shelter with these utensils on their stomachs, to communicate to the passing helicopters that they were hungry. The message got through, and after that the helicopter made regular rounds of the shelter, airdropping food and other basic needs. Prashant found that a large number of children had been orphaned. He brought them together and put up a polythene sheet shelter for them."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43646a1714c6','ch_3ea2a94bda20','text','{"text": "Women were mobilised to look after them, while the men secured food and materials for the shelter. As the weeks passed, Prashant was quick to recognise that the women and children were sinking deeper and deeper in their grief. He persuaded the women to start working in the food-forwork programme started by an NGO, and for the children he organised sports events. He himself loved to play cricket, and so he organised cricket matches for children."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_331c47ddaf24','ch_3ea2a94bda20','text','{"text": "Prashant engaged, with other volunteers, in helping the widows and children to pick up the broken pieces of their lives. The initial government plan was to set up institutions for orphans and widows. However, this step was successfully resisted, as it was felt that in such institutions, children would grow up without love, and widows would suffer from stigma and loneliness."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9ed60a0a146','ch_3ea2a94bda20','text','{"text": "Prashant’s group believed orphans should be resettled in their own community itself, possibly in new foster families made up of childless widows and children without adult care. It is six months after the devastation of the super cyclone. This time Prashant’s wounded spirit has healed simply because he had no time to bother about his own pain. His handsome, youthful face is what the widows and orphaned children of his village seek out most in their darkest hour of grief."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c946e65dc8a7','ch_3ea2a94bda20','heading','{"level": 2, "text": "Harsh Mander"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd5c25d647ac','ch_3ea2a94bda20','text','{"text": "*********"}',19);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_46a3fd4036b9','bk_ncert_english','10-7-the-last-leaf','10.7 The Last Leaf',NULL,'public',29,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a8f82c1e1c4','ch_46a3fd4036b9','text','{"text": "SUE and Johnsy, two young artists, shared a small flat. The flat was on the third storey of an old house. Johnsy fell very seriously ill in November. She had pneumonia. She would lie in her bed without moving, just gazing out of the window. Sue, her friend, became very worried. She sent for the doctor. Although he came every day there was no change in Johnsy’s condition."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e042ec56856','ch_46a3fd4036b9','text','{"text": "One day the doctor took Sue aside and asked her, ’Is anything worrying Johnsy?’"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04b7bf65e08f','ch_46a3fd4036b9','text','{"text": "‘No,’ replied Sue."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f8a545d76ba','ch_46a3fd4036b9','text','{"text": "‘But why do you ask?’ The doctor said"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b7a37615569','ch_46a3fd4036b9','text','{"text": "‘Johnsy, it seems, has made up her mind that she is not going to get well. If she doesn’t want to live, medicines will not help her.’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad947940dc5e','ch_46a3fd4036b9','text','{"text": "Sue tried her best to make Johnsy take an interest in things around her. She talked about clothes and fashions, but Johnsy did not respond. Johnsy continued to lie still on her bed. Sue brought her drawing-board into Johnsy’s room and started painting. To take Johnsy’s mind off her illness, she whistled while working. Suddenly Sue heard Johnsy whisper something. She quickly rushed to the bed and heard Johnsy counting backwards."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5796c79b1276','ch_46a3fd4036b9','text','{"text": "She was looking out of the window and was saying, ‘Twelve!’ After sometime she whispered"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_744026ee635b','ch_46a3fd4036b9','text','{"text": "‘eleven’, then"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f51c512a9c2','ch_46a3fd4036b9','text','{"text": "‘ten’, then"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e30f0fc21709','ch_46a3fd4036b9','text','{"text": "‘nine’, ‘eight’, ‘seven’. Sue anxiously looked out of the window. She saw an old ivy creeper climbing half-way up the brick wall opposite their window. In the strong wind outside, the creeper was shedding its leaves."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05cf49f08dc8','ch_46a3fd4036b9','text','{"text": "‘What is it, dear?’ Sue asked."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c879ceb81c96','ch_46a3fd4036b9','text','{"text": "‘Six,’ whispered Johnsy."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f52a6c063fe','ch_46a3fd4036b9','text','{"text": "‘They are falling faster now. Three days ago there were almost a hundred leaves. There are only five left now.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_685c0dc22b5b','ch_46a3fd4036b9','text','{"text": "‘It is autumn,’ said Sue, ‘and the leaves will fall.’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e658742d4812','ch_46a3fd4036b9','text','{"text": "‘When the last leaf falls, I will die,’ said Johnsy with finality."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_501aecb82f6b','ch_46a3fd4036b9','text','{"text": "‘I have known this for the last three days.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f50ed7de9366','ch_46a3fd4036b9','text','{"text": "‘Oh, that’s nonsense,’ replied Sue."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ae7589e3530','ch_46a3fd4036b9','text','{"text": "‘What have old ivy leaves to do with your getting well? The doctor is confident that you will get better.’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_108bb076417f','ch_46a3fd4036b9','text','{"text": "Johnsy did not say anything. Sue went and brought her a bowl of soup."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfe49daf5a33','ch_46a3fd4036b9','text','{"text": "‘I don’t want any soup,’ said Johnsy."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7adfd263ac6','ch_46a3fd4036b9','text','{"text": "‘I am not hungry… Now there are only four leaves left. I want to see the last one fall before it gets dark. Then I will sleep forever.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c78512d4d13','ch_46a3fd4036b9','text','{"text": "Sue sat on Johnsy’s bed, kissed her and said, ‘You are not going to die. I can’t draw the curtain for I need the light. I want to finish the painting and get some money for us. Please, my dear friend,’ she begged Johnsy, ‘promise not to look out of the window while I paint.’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe8d182b01f1','ch_46a3fd4036b9','text','{"text": "‘All right,’ said Johnsy."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d150cd0bac3','ch_46a3fd4036b9','text','{"text": "‘Finish your painting soon for I want to see the last leaf fall. I’m tired of waiting. I have to die, so let me go away peacefully like one of those poor, tired leaves.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_369e09daa4e7','ch_46a3fd4036b9','text','{"text": "‘Try to sleep,’ said Sue."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6f1a3e1d705','ch_46a3fd4036b9','text','{"text": "‘I have to paint an old miner. I will call Behrman up to be my model.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e35dae759ce','ch_46a3fd4036b9','text','{"text": "Sue rushed down. Behrman lived on the ground floor. He was a sixty-year-old painter. His lifelong dream was to paint a masterpiece but that had remained a dream. Sue poured out her worries to Behrman. She told him how Johnsy was convinced that she would die when the last leaf fell."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db1d947a34e5','ch_46a3fd4036b9','text','{"text": "‘Is she stupid?’ asked Behrman."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63cf2a4af9e7','ch_46a3fd4036b9','text','{"text": "‘How can she be so foolish?’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15ed6b1ac410','ch_46a3fd4036b9','text','{"text": "‘She is running a high temperature,’complained Sue."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_912a35402eee','ch_46a3fd4036b9','text','{"text": "‘She refuses to eat or drink and that worries me a lot.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abe08140c4d8','ch_46a3fd4036b9','text','{"text": "‘I will come with you and see Johnsy,’ Behrman said."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93ea46f1f81a','ch_46a3fd4036b9','text','{"text": "They tiptoed into the room. Johnsy was sleeping. Sue drew the curtains together and they went to the next room. She peeped out through the window. There was only one leaf on the creeper. It was raining heavily and an icy-cold wind was blowing. It seemed as though the leaf would fall any minute now. Behrman did not say a word. He went back to his room. Johnsy woke up next morning. In a feeble voice she asked Sue to draw the curtains. Sue was nervous. She drew back the curtains very reluctantly."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e926b4443e85','ch_46a3fd4036b9','text','{"text": "‘Oh!’ Sue exclaimed as she looked at the vine creeper."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a6b0ca17ad8','ch_46a3fd4036b9','text','{"text": "‘Look, there is still one leaf on the creeper. It looks quite green and healthy. In spite of the storm and the fierce winds, it didn’t fall.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d2a72a9f0ac','ch_46a3fd4036b9','text','{"text": "‘I heard the wind last night,’ said Johnsy."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3cfa6cb344a','ch_46a3fd4036b9','text','{"text": "‘I thought it would have fallen. It will surely fall today. Then I’ll die.’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0dbee531f16','ch_46a3fd4036b9','text','{"text": "‘You won’t die,’ said Sue energetically."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b795e097d9d1','ch_46a3fd4036b9','text','{"text": "‘You have to live for your friends. What would happen to me if you die?’ Johnsy smiled weakly and closed her eyes. After every hour or so she would look out of the window and find the leaf still there. It seemed to be clinging to the creeper. In the evening, there was another storm but the leaf did not fall. Johnsy lay for a long time looking at the leaf. Then she called out to Sue."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ddb10c9739b','ch_46a3fd4036b9','text','{"text": "‘I have been a bad girl. You have looked after me so lovingly and I have not cooperated with you. I have been depressed and gloomy. The last leaf has shown me how wicked I have been. I have realised that it is a sin to want to die.’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82b9174acc95','ch_46a3fd4036b9','text','{"text": "Sue hugged Johnsy. Then she gave her lots of hot soup and a mirror. Johnsy combed her hair and smiled brightly. In the afternoon the doctor came. After examining his patient he told Sue, ‘Johnsy now has the will to live. I am confident she’ll recover soon. Now I must go downstairs and see Behrman. He is also suffering from pneumonia. But I am afraid, there is no hope for him.’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a91fa5afbf0','ch_46a3fd4036b9','text','{"text": "The next morning Sue came and sat on Johnsy’s bed. Taking Johnsy’s hand in hers she said, ‘I have something to tell you. Mr Behrman died of pneumonia this morning. He was ill for only two days. The first day the janitor found him on his bed. His clothes and shoes were wet and he was shivering. He had been out in that stormy night.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a864395e9f11','ch_46a3fd4036b9','text','{"text": "Then they found a ladder and a lantern still lighted lying near his bed. There were also some brushes and green and yellow paints on the floor near the ladder."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_338a76978d8b','ch_46a3fd4036b9','text','{"text": "‘Johnsy dear,’ said Sue, ‘look out of the window."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_690bbdf21bdb','ch_46a3fd4036b9','text','{"text": "Look at that ivy leaf. Haven’t you wondered why it doesn’t flutter when the wind blows? That’s Behrman’s masterpiece. He painted it the night the last leaf fell.’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90f8992ab8e9','ch_46a3fd4036b9','heading','{"level": 2, "text": "O. Henry"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c8dec55a622','ch_46a3fd4036b9','text','{"text": "*********"}',47);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_263f79f2fd33','bk_ncert_english','10-8-a-house-is-not-a-home','10.8 A House Is Not A Home',NULL,'public',30,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9aa418553fd1','ch_263f79f2fd33','text','{"text": "MY first year of high school felt awkward. After leaving junior high at the head of my class with all the seniority the upper grade levels could afford me, it felt strange starting over as a freshman. The school was twice as big as my old school, and to make matters worse, my closest friends were sent to a different high school. I felt very isolated. I missed my old teachers so much that I would go back and visit them."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53d6d0473d33','ch_263f79f2fd33','text','{"text": "They would encourage me to get involved in school activities so that I could meet new people. They told me that in time I would adjust and probably end up loving my new school more than I had my old one. They made me promise that when that happened I would still come by and visit them from time to time. I understood the psychology in what they were saying, but I took some comfort in it nonetheless."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0203fc8234d','ch_263f79f2fd33','text','{"text": "One Sunday afternoon, not long after I had started high school, I was sitting at home at our dining-room table doing homework. It was a cold and windy fall day, and we had a fire going in our fireplace. As usual, my red tabby cat was lying on top of all my papers, purring loudly and occasionally swatting at my pen for entertainment’s sake. She was never far from me. I had rescued her when she was a kitten, and somehow she knew that I was the one responsible for giving her"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a5ef9983eed','ch_263f79f2fd33','text','{"text": "‘the good life’."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d273bb8ee311','ch_263f79f2fd33','text','{"text": "My mother kept stoking the fire to keep the house nice and warm. Suddenly, I smelled something strange, and then I noticed it... smoke pouring in through the seams of the ceiling. The smoke began to fill the room so quickly that we could barely see. Groping our way to the front door, we all ran out into the front yard. By the time we made our way outside, the whole roof was engulfed in flames and it was spreading quickly."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1110a60e03bd','ch_263f79f2fd33','text','{"text": "I ran to the neighbours to call the fire department, while I watched my mother run back into the house. My mother then ran out of the house carrying a small metal box full of important documents. She dropped the case on the lawn and, in a crazed state, ran back into the house. I knew what she was after. My father had died when I was young, and I was certain that she was not going to let his pictures and letters go up in flames. They were the only things that she had to remember him by."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eeba912d5c51','ch_263f79f2fd33','text','{"text": "Still I screamed at her, ‘Mom! No!’ I was about to run after her when I felt a large hand hold me back. It was a fireman. I hadn’t even noticed that the street had already filled with fire trucks. I was trying to free myself from his grasp, yelling, ‘You don’t understand, my mother’s in there!’ He held on to me while other firefighters ran into the house. He knew that I wasn’t acting very logically and that if he were to let go, I’d run. He was right."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd7918f1a76e','ch_263f79f2fd33','text','{"text": "‘It’s all right, they’ll get her,’ he said. He wrapped a blanket around me and sat me down in our car. Soon after that, a fireman emerged from our house with my mom in tow. He quickly took her over to the truck and put an oxygen mask on her. I ran over and hugged her. All those times I ever argued with her and hated her vanished at the thought of losing her."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c363a2c28fa','ch_263f79f2fd33','text','{"text": "‘She’s going to be okay,’ said the fireman."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab88cd5d7d15','ch_263f79f2fd33','text','{"text": "‘She just inhaled a little smoke.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ff79f4ea66b','ch_263f79f2fd33','text','{"text": "And then he ran back to fight the fire while my mother and I sat there dazed. I remember watching my house burn down and thinking that there was nothing I could do about it. Five hours later, the fire was finally out. Our house was almost completely burned down. But then it struck me ... I hadn’t seen my cat. Where was my cat? Much to my horror, I realised that she was nowhere to be found. Then all at once it hit me— the new school, the fire, my cat— I broke down in tears and cried and cried."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c832c2be2a9','ch_263f79f2fd33','text','{"text": "I was suffering loss, big time. The firemen wouldn’t let us go back into the house that night. It was still too dangerous. Dead or alive, I couldn’t imagine leaving without knowing about my cat. Regardless, I had to go. We piled into the car with just the clothes on our backs and a few of the firemen’s blankets, and made our way to my grandparents’ house to spend the night. The next day, Monday, I went to school."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1cc8e4a7264','ch_263f79f2fd33','text','{"text": "When the fire broke out, I was still wearing the dress I had worn to church that morning but I had no shoes! I had kicked them off when I was doing my homework. They became yet another casualty of the fire. So I had to borrow some tennis shoes from my aunt. Why couldn’t I just stay home from school? My mother wouldn’t hear of it, but I was totally embarrassed by everything. The clothes I was wearing looked weird, I had no books or homework, and my backpack was gone."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6c17004242c','ch_263f79f2fd33','text','{"text": "I had my life in that backpack! The more I tried to fit in, the worse it got. Was I destined to be an outcast and a geek all my life? That’s what it felt like. I didn’t want to grow up, change or have to handle life if it was going to be this way. I just wanted to curl up and die. I walked around school like a zombie. Everything felt surreal, and I wasn’t sure what was going to happen. All the security I had known, from my old school, my friends, my house and my cat had all been ripped away."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9f47fb594a3','ch_263f79f2fd33','text','{"text": "When I walked through what used to be my house after school that day, I was shocked to see how much damage there was— whatever hadn’t burned was destroyed by the water and chemicals they had used to put out the fire. The only material things not destroyed were the photo albums, documents and some other personal items that my mother had managed to heroically rescue. But my cat was gone and my heart ached for her. There was no time to grieve. My mother rushed me out of the house."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c47813e800c5','ch_263f79f2fd33','text','{"text": "We would have to find a place to live, and I would have to go buy some clothes for school. We had to borrow money from my grandparents because there were no credit cards, cash or even any identification to be able to withdraw money from the bank. Everything had gone up in smoke. That week the rubble that used to be our house was being cleared off the lot. Even though we had rented an apartment nearby, I would go over to watch them clear away debris, hoping that my cat was somewhere to be found."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62eb390b7ab7','ch_263f79f2fd33','text','{"text": "She was gone. I kept thinking about her as that vulnerable little kitten. In the early morning when I would disturb her and get out of bed, she would tag along after me, climb up my robe and crawl into my pocket to fall asleep. I was missing her terribly. It always seems that bad news spreads quickly, and in my case it was no different. Everyone in high school, including the teachers, was aware of my plight. I was embarrassed as if somehow I were responsible."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_891d37323fbd','ch_263f79f2fd33','text','{"text": "What a way to start off at a new school! This was not the kind of attention I was looking for. The next day at school, people were acting even more strange than usual. I was getting ready for gym class at my locker. People were milling around me, asking me to hurry up. I thought it strange, but in the light of the past few weeks, nothing would surprise me. It almost seemed that they were trying to shove me into the gym — then I saw why."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04849ea687b6','ch_263f79f2fd33','text','{"text": "There was a big table set up with all kinds of stuff on it, just for me. They had taken up a collection and bought me school supplies, notebooks, all kinds of different clothes— jeans, tops, sweatsuits. It was like Christmas. I was overcome by emotion. People who had never spoken to me before were coming up to me to introduce themselves. I got all kinds of invitations to their houses. Their genuine outpouring of concern really touched me."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cba10981d3e1','ch_263f79f2fd33','text','{"text": "In that instant, I finally breathed a sigh of relief and thought for the first time that things were going to be okay. I made friends that day. A month later, I was at my house watching them rebuild it. But this time it was different— I wasn’t alone. I was with two of my new friends from school. It took a fire for me to stop focusing on my feelings of insecurity and open up to all the wonderful people around me."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32d5af8637f4','ch_263f79f2fd33','text','{"text": "Now I was sitting there watching my house being rebuilt when I realised my life was doing the same thing. While we sat there on the curb, planning my new bedroom, I heard someone walk up to me from behind and say, ‘Does this belong to you?’ When I turned around to see who it was, I couldn’t believe my eyes. A woman was standing there holding my cat! I leapt up and grabbed her out of the woman’s arms. I held her close to me and cried into that beautiful orange fur. She purred happily."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b55dd96260ef','ch_263f79f2fd33','text','{"text": "My friends were hugging me, hugging the cat and jumping around. Apparently, my cat had been so freaked by the fire that she ran over a mile away. Her collar had our phone number on it, but our phones had been destroyed and disconnected. This wonderful woman took her in and worked hard to find out whose cat it was. Somehow, she knew this cat was loved and sorely missed."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6630c327ab66','ch_263f79f2fd33','text','{"text": "As I sat there with my friends and my cat curled up in my lap, all the overwhelming feelings of loss and tragedy seemed to diminish. I felt gratitude for my life, my new friends, the kindness of a stranger and the loud purr of my beloved cat. My cat was back and so was I."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a041ab3dd4d8','ch_263f79f2fd33','heading','{"level": 2, "text": "Zan Gaudioso"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1501df3f6978','ch_263f79f2fd33','text','{"text": "*********"}',25);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_3583216a22b8','bk_ncert_english','10-9-the-accidental-tourist','10.9 The Accidental Tourist',NULL,'public',31,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81ecf6259881','ch_3583216a22b8','text','{"text": "OF all the things I am not very good at, living in the real world is perhaps the most outstanding. I am constantly filled with wonder at the number of things that other people do without any evident difficulty that are pretty much beyond me. I cannot tell you the number of times that I have gone looking for the lavatory in a cinema, for instance, and ended up standing in an alley on the wrong side of a selflocking door."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c496e2c23426','ch_3583216a22b8','text','{"text": "My particular specialty now is returning to hotel desks two or three times a day and asking what my room number is. I am, in short, easily confused. I was thinking about this the last time we went en famille on a big trip. It was at Easter, and we were flying to England for a week. When we arrived at Logan Airport in Boston and were checking in, I suddenly remembered that I had recently joined British Airways’ frequent flyer programme."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fc2b8959e96','ch_3583216a22b8','text','{"text": "I also remembered that I had put the card in the carry-on bag that was hanging around my neck. And here’s where the trouble started. The zip on the bag was jammed. So I pulled on it and yanked at it, with grunts and frowns and increasing consternation. I kept this up for some minutes but it wouldn’t budge, so I pulled harder and harder, with more grunts. Well, you can guess what happened. Abruptly the zip gave way."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a476f897eb0','ch_3583216a22b8','text','{"text": "The side of the bag flew open and everything within — newspaper cuttings and other loose papers, a 14- ounce tin of pipe tobacco, magazines, passport, English money, film — was extravagantly ejected over an area about the size of a tennis court. I watched dumbstruck as a hundred carefully sorted documents came raining down in a fluttery cascade, coins bounced to a variety of noisy oblivions and the now-lidless tin of tobacco rolled crazily across the concourse disgorging its contents as it went."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b57a80d9c5eb','ch_3583216a22b8','text','{"text": "‘My tobacco!’ I cried in horror, thinking what I would have to pay for that much tobacco in England now that another Budget had come and gone, and then changed the cry to"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03f0eecabaad','ch_3583216a22b8','text','{"text": "‘My finger! My finger!’ as I discovered that I had gashed my finger on the zip and was shedding blood in a lavish manner."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76e573cf39d4','ch_3583216a22b8','text','{"text": "(I am not very good around flowing blood generally, but when it’s my own— well, I think hysterics are fully justified.) Confused and unable to help, my hair went into panic mode. It was at this point that my wife looked at me with an expression of wonder — not anger or exasperation, but just simple wonder — and said, ‘I can’t believe you do this for a living.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c00e56cbc3b','ch_3583216a22b8','text','{"text": "But I’m afraid it’s so. I always have catastrophes when I travel. Once on an aeroplane, I leaned over to tie a shoelace just at the moment someone in the seat ahead of me threw his seat back into full recline, and found myself pinned helplessly in the crash position. It was only by clawing the leg of the man sitting next to me that I managed to get myself freed. On another occasion, I knocked a soft drink onto the lap of a sweet little lady sitting beside me."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e3a8e2aaf8c','ch_3583216a22b8','text','{"text": "The flight attendant came and cleaned her up, and brought me a replacement drink, and instantly I knocked it onto the woman again. To this day, I don’t know how I did it. I just remember reaching out for the new drink and watching helplessly as my arm, like some cheap prop in one of those 1950s horror movies with a name like The Undead Limb, violently swept the drink from its perch and onto her lap."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25a8bc69c06e','ch_3583216a22b8','text','{"text": "The lady looked at me with the stupefied expression you would expect to receive from someone whom you have repeatedly drenched, and uttered an oath that started with"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91843cb70570','ch_3583216a22b8','text','{"text": "‘Oh’, finished with"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2878e1ac460','ch_3583216a22b8','text','{"text": "‘sake’ and in between had some words that I have never heard uttered in public before, certainly not by a nun. This, however, was not my worst experience on a plane flight. My worst experience was when I was writing important thoughts in a notebook (‘buy socks’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a489f9d98f4c','ch_3583216a22b8','text','{"text": ", ‘clutch drinks carefully’, etc.), sucking thoughtfully on the end of my pen as you do, and fell into conversation with an attractive young lady in the next seat. I amused her for perhaps 20 minutes with a scattering of urbane bons mots, then retired to the lavatory where I discovered that the pen had leaked and that my mouth, chin, tongue, teeth and gums were now a striking, scrub-resistant navy blue, and would remain so for several days."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae4cd79b7865','ch_3583216a22b8','text','{"text": "So you will understand, I trust, when I tell you how much I ache to be suave. I would love, just once in my life, to rise from a dinner table without looking as if I have just experienced an extremely localised seismic event, get in a car and close the door without leaving 14 inches of coat outside, wear light-coloured trousers without discovering at the end of the day that I have at various times sat on chewing gum, ice cream, cough syrup and motor oil. But it is not to be."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c38357c270a3','ch_3583216a22b8','text','{"text": "Now on planes when the food is delivered, my wife says:"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_422ff76f66fb','ch_3583216a22b8','text','{"text": "‘Take the lids off the food for Daddy’ or"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75d19168ccc4','ch_3583216a22b8','text','{"text": "‘Put your hoods up, children. Daddy''s about to cut his meat’. Of course, this is only when I am flying with my family. When I am on my own, I don’t eat, drink or lean over to tie my shoelaces, and never put a pen anywhere near my mouth. I just sit very, very quietly, sometimes on my hands to keep them from flying out unexpectedly and causing liquid mischief. It’s not much fun, but it does at least cut down on the laundry bills. I never did get my frequent flyer miles, by the way. I never do."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9452620d3943','ch_3583216a22b8','text','{"text": "I couldn''t find the card in time. This has become a real frustration for me. Everyone I know — everyone— is forever flying off to Bali first class with their air miles. I never get to collect anything. I must fly 100,000 miles a year, yet I have accumulated only about 212 air miles divided between twenty-three airlines."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5e0f2d566c4','ch_3583216a22b8','text','{"text": "This is because either I forget to ask for the air miles when I check in, or I remember to ask for them but the airline then manages not to record them, or the check-in clerk informs me that I am not entitled to them. In January, on a flight to Australia — a flight for which I was going to get about a zillion air miles — the clerk shook her head when I presented my card and told me I was not entitled to any."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b0293c89dda','ch_3583216a22b8','text','{"text": "‘Why?’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50fd5b81513f','ch_3583216a22b8','text','{"text": "‘The ticket is in the name of B. Bryson and the card is in the name of W. Bryson.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cc57296fddc','ch_3583216a22b8','text','{"text": "I explained to her the close and venerable relationship between Bill and William, but she wouldn’t have it. So I didn’t get my air miles, and I won’t be flying to Bali first class just yet. Perhaps just as well, really. I could never go that long without eating."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb0b56662957','ch_3583216a22b8','heading','{"level": 2, "text": "Bill Bryson"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5186a3f9b5b6','ch_3583216a22b8','text','{"text": "*********"}',24);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b3ec39e89a8e','bk_ncert_english','10-10-the-beggar','10.10 The Beggar',NULL,'public',32,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10fcb89f844b','ch_b3ec39e89a8e','text','{"text": "‘KIND sir, have pity; turn your attention to a poor, hungry man! For three days I have had nothing to eat; I haven’t five copecks for a lodging, I swear it before God."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_241cc739df12','ch_b3ec39e89a8e','text','{"text": "For eight years I was a village schoolteacher and then I lost my place through intrigues. I fell a victim to calumny. It is a year now since I have had anything to do.’"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b93a46bd1e6','ch_b3ec39e89a8e','text','{"text": "The advocate, Sergei, looked at the ragged, fawn-coloured overcoat of the suppliant, at his dull, drunken eyes, at the red spot on either cheek, and it seemed to him as if he had seen this man somewhere before."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ce087d4e2c7','ch_b3ec39e89a8e','text','{"text": "‘I have now had an offer of a position in the province of Kaluga,’ the mendicant went on, ‘but I haven’t the money to get there."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43d6f7089d7a','ch_b3ec39e89a8e','text','{"text": "Help me kindly; I am ashamed to ask, but — I am obliged to by circumstances.’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1679e279cc26','ch_b3ec39e89a8e','text','{"text": "Sergei’s eyes fell on the man’s overshoes, one of which was high and the other low, and he suddenly remembered something."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ada6582cc51','ch_b3ec39e89a8e','text','{"text": "‘Look here, it seems to me I met you the day before yesterday in Sadovya Street,’ he said;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0779fc02ecf6','ch_b3ec39e89a8e','text','{"text": "‘but you told me then that you were a student who had been expelled, and not a village schoolteacher. Do you remember?’"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dc580ea2123','ch_b3ec39e89a8e','text','{"text": "‘N-no, that can’t be so,’ mumbled the beggar, taken aback."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77fa282c2e8b','ch_b3ec39e89a8e','text','{"text": "‘I am a village schoolteacher, and if you like I can show you my papers.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_889a01891e88','ch_b3ec39e89a8e','text','{"text": "‘Have done with lying! You called yourself a student and even told me what you had been expelled for. Don’t you remember?’ Sergei flushed and turned from the ragged creature with an expression of disgust."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbe095066d73','ch_b3ec39e89a8e','text','{"text": "‘This is dishonesty, my dear sir!’ he cried angrily."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8740312df2af','ch_b3ec39e89a8e','text','{"text": "‘This is swindling — I shall send the police for you, damn you!’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_438e1ec12147','ch_b3ec39e89a8e','text','{"text": "‘Sir!’ he said, laying his hand on his heart, ‘the fact is I was lying! I am neither a student nor a schoolteacher. All that was fiction. Formerly I sang in a Russian choir and was sent away for drunkenness. But what else can I do? I can’t get along without lying. No one will give me anything when I tell the truth, what can I do?’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f80b1ff67b2c','ch_b3ec39e89a8e','text','{"text": "‘What can you do? You ask what you can do?’ cried Sergei, coming close to him."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33c1ea1784ac','ch_b3ec39e89a8e','text','{"text": "‘Work! That’s what you can do! You must work!’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c9b711ebb60','ch_b3ec39e89a8e','text','{"text": "‘Work — yes. I know that myself; but where can I find work?’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e1627159390','ch_b3ec39e89a8e','text','{"text": "‘How would you like to chop wood for me?’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04535e4f76b1','ch_b3ec39e89a8e','text','{"text": "‘I wouldn’t refuse to do that, but in these days even skilled wood-cutters find themselves sitting without bread.’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2901e74f5a72','ch_b3ec39e89a8e','text','{"text": "‘Will you come and chop wood for me?’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7aaa199da78','ch_b3ec39e89a8e','text','{"text": "‘Yes sir, I will.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f84bebff7bd4','ch_b3ec39e89a8e','text','{"text": "‘Very well; we’ll soon find out.’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_545b3069b4e1','ch_b3ec39e89a8e','text','{"text": "Sergei hastened along, rubbing his hands. He called his cook out of the kitchen."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ffce946c83a','ch_b3ec39e89a8e','text','{"text": "‘Here, Olga,’ he said, ‘take this gentleman into the wood-shed and let him chop wood.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b25565672de','ch_b3ec39e89a8e','text','{"text": "The scarecrow of a beggar shrugged his shoulders, as if in perplexity, and went irresolutely after the cook. It was obvious from his gait that he had not consented to go and chop wood because he was hungry and wanted work, but simply from pride and shame and because he had been trapped by his own words. It was obvious, too, that his strength had been undermined by vodka and that he was unhealthy and did not feel the slightest inclination for toil. Sergei hurried into the dining-room."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88a8738e045b','ch_b3ec39e89a8e','text','{"text": "From its windows one could see the wood-shed and everything that went on in the yard. Standing at the window, Sergei saw the cook and the beggar come out into the yard by the back door and make their way across the dirty snow to the shed. Olga glared wrathfully at her companion, shoved him aside with her elbow, unlocked the shed, and angrily banged the door. Next he saw the pseudo-teacher seat himself on a log and become lost in thought with his red cheeks resting on his fists."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed15876429c2','ch_b3ec39e89a8e','text','{"text": "The woman flung down an axe at his feet, spat angrily, and, judging from the expression of her lips, began to scold him. The beggar irresolutely pulled a billet of wood towards him, set it up between his feet, and tapped it feebly with the axe. The billet wavered and fell down. The beggar again pulled it to him, blew on his freezing hands, and tapped it with his axe cautiously, as if afraid of hitting his overshoe or of cutting off his finger; the stick of wood again fell to the ground."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8ed35003fec','ch_b3ec39e89a8e','text','{"text": "Sergei’s anger had vanished and he now began to feel a little sorry and ashamed of himself for having set a spoiled, drunken, perhaps sick man to work at menial labour in the cold. An hour later Olga came in and announced that the wood had all been chopped."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16f3ee82da74','ch_b3ec39e89a8e','text','{"text": "‘Good! Give him half a rouble,’ said Sergei."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bb9242e57b3','ch_b3ec39e89a8e','text','{"text": "‘If he wants to he can come back and cut wood on the first day of each month. We can always find work for him.’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef1a57bf6318','ch_b3ec39e89a8e','text','{"text": "On the first of the month the waif made his appearance and again earned half a rouble, although he could barely stand on his legs. From that day on he often appeared in the yard and every time work was found for him. Now he would shovel snow, now put the wood-shed in order, now beat the dust out of rugs and mattresses. Every time he received from twenty to forty copecks, and once, even a pair of old trousers were sent out to him."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61ceb2085fb4','ch_b3ec39e89a8e','text','{"text": "When Sergei moved into another house he hired him to help in the packing and hauling of the furniture. This time the waif was sober, gloomy, and silent. He hardly touched the furniture, and walked behind the wagons hanging his head, not even making a pretence of appearing busy. He only shivered in the cold and became embarrassed when the carters jeered at him for his idleness, his feebleness, and his tattered, fancy overcoat. After the moving was over Sergei sent for him."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7cedc51364bc','ch_b3ec39e89a8e','text','{"text": "‘Well, I am happy that my words have taken effect,’’ he said, handing him a rouble."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1af18f3fb51','ch_b3ec39e89a8e','text','{"text": "‘Here’s for your pains. I see you are sober and have no objection to work. What is your name?’’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_137259e1f246','ch_b3ec39e89a8e','text','{"text": "‘Lushkoff.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf0b84f3b61e','ch_b3ec39e89a8e','text','{"text": "‘Well, Lushkoff, I can now offer you some other, cleaner employment. Can you write?’’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c1dcecf8241','ch_b3ec39e89a8e','text','{"text": "‘I can.’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76b1edf6a506','ch_b3ec39e89a8e','text','{"text": "‘Then take this letter to a friend of mine tomorrow and you will be given some copying to do. Work hard, don’t drink, and remember what I have said to you. Goodbye!’ Pleased at having put a man on the right path, Sergei tapped Lushkoff kindly on the shoulder and even gave him his hand at parting. Lushkoff took the letter, and from that day forth came no more to the yard for work. Two years went by."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd814cbd8500','ch_b3ec39e89a8e','text','{"text": "Then one evening, as Sergei was standing at the ticket window of a theatre paying for his seat, he noticed a little man beside him with a coat collar of curly fur and a worn sealskin cap. This little individual timidly asked the ticket seller for a seat in the gallery and paid for it in copper coins."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b752591b1bc6','ch_b3ec39e89a8e','text','{"text": "‘Lushkoff, is that you?’ cried Sergei, recognising in the little man his former wood-chopper."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbda1cf47ae0','ch_b3ec39e89a8e','text','{"text": "‘How are you? What are you doing? How is everything with you?’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9173d8247468','ch_b3ec39e89a8e','text','{"text": "‘All right. I am a notary now and am paid thirty-five roubles a month.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c48df54a1f4f','ch_b3ec39e89a8e','text','{"text": "‘Thank Heaven! That’s fine! I am delighted for your sake."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ced82fc4a87','ch_b3ec39e89a8e','text','{"text": "I am very, very glad, Lushkoff. You see, you are my godson, in a sense. I gave you a push along the right path, you know. Do you remember what a roasting I gave you, eh? I nearly had you sinking into the ground at my feet that day. Thank you, old man, for not forgetting my words.’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed70f277ab6e','ch_b3ec39e89a8e','text','{"text": "‘Thank you, too.’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b90d4e44733','ch_b3ec39e89a8e','text','{"text": "said Lushkoff."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_370858bb397d','ch_b3ec39e89a8e','text','{"text": "‘If I hadn’t come to you then I might still have been calling myself a teacher or a student to this day."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2afafc217cf6','ch_b3ec39e89a8e','text','{"text": "Yes, by flying to your protection I dragged myself out of a pit.’"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17ac54eda0a6','ch_b3ec39e89a8e','text','{"text": "‘I am very glad, indeed.’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d201d5c5caf','ch_b3ec39e89a8e','text','{"text": "‘Thank you for your kind words and deeds. I am very grateful to you and to your cook. God bless that good and noble woman! You spoke finely then, and I shall be indebted to you to my dying day; but, strictly speaking, it was your cook, Olga, who saved me.’"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3592ec4ac310','ch_b3ec39e89a8e','text','{"text": "‘How is that?’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de5097437184','ch_b3ec39e89a8e','text','{"text": "‘When I used to come to your house to chop wood she used to begin:"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f45b6bb98f1d','ch_b3ec39e89a8e','text','{"text": "‘Oh, you sot, you! Oh, you miserable creature! There’s nothing for you but ruin.’"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_acbdf0a33a35','ch_b3ec39e89a8e','text','{"text": "And then she would sit down opposite me and grow sad, look into my face and weep."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ff46f9e399d','ch_b3ec39e89a8e','text','{"text": "‘Oh, you unlucky man! There is no pleasure for you in this world and there will be none in the world to come. You drunkard! You will burn in hell. Oh, you unhappy one!’ And so she would carry on, you know, in that strain. I can’t tell you how much misery she suffered, how many tears she shed for my sake. But the chief thing was — she used to chop the wood for me. Do you know, sir, that I did not chop one single stick of wood for you? She did it all."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea86daa37f5c','ch_b3ec39e89a8e','text','{"text": "Why this saved me, why I changed, why I stopped drinking at the sight of her I cannot explain. I only know that, owing to her words and noble deeds, a change took place in my heart; she set me right and I shall never forget it. However, it is time to go now; there goes the bell.’"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2536d8cb420a','ch_b3ec39e89a8e','text','{"text": "Lushkoff bowed and departed to the gallery."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_930f39e22222','ch_b3ec39e89a8e','heading','{"level": 2, "text": "Anton Chekhov"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9484bf5edaa5','ch_b3ec39e89a8e','text','{"text": "*********"}',59);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_8d731d1c1d7a','bk_ncert_english','10-11-a-letter-to-god','10.11 A Letter to God',NULL,'public',33,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77ac78a48902','ch_8d731d1c1d7a','text','{"text": "THE house — the only one in the entire valley — sat on the crest of a low hill. From this height one could see the river and the field of ripe corn dotted with the flowers that always promised a good harvest. The only thing the earth needed was a downpour or at least a shower. Throughout the morning Lencho — who knew his fields intimately — had done nothing else but see the sky towards the north-east."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adb25fa33cd6','ch_8d731d1c1d7a','text','{"text": "‘Now we’re really going to get some water, woman.’"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce6429f34595','ch_8d731d1c1d7a','text','{"text": "The woman who was preparing supper, replied, ‘Yes, God willing’. The older boys were working in the field, while the smaller ones were playing near the house until the woman called to them all, ‘Come for dinner’. It was during the meal that, just as Lencho had predicted, big drops of rain began to fall. In the north-east huge mountains of clouds could be seen approaching. The air was fresh and sweet."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7325db7e70c0','ch_8d731d1c1d7a','text','{"text": "The man went out for no other reason than to have the pleasure of feeling the rain on his body, and when he returned he exclaimed, ‘These aren’t raindrops falling from the sky, they are new coins. The big drops are ten cent pieces and the little ones are fives.’"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7393f3ce918','ch_8d731d1c1d7a','text','{"text": "With a satisfied expression he regarded the field of ripe corn with its flowers, draped in a curtain of rain. But suddenly a strong wind began to blow and along with the rain very large hailstones began to fall. These truly did resemble new silver coins. The boys, exposing themselves to the rain, ran out to collect the frozen pearls."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c5dbdc4190a','ch_8d731d1c1d7a','text','{"text": "‘It’s really getting bad now,’ exclaimed the man."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71d36d6de992','ch_8d731d1c1d7a','text','{"text": "‘I hope it passes quickly.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae0a78658b9f','ch_8d731d1c1d7a','text','{"text": "It did not pass quickly. For an hour the hail rained on the house, the garden, the hillside, the cornfield, on the whole valley. The field was white, as if covered with salt. Not a leaf remained on the trees. The corn was totally destroyed. The flowers were gone from the plants. Lencho’s soul was filled with sadness. When the storm had passed, he stood in the middle of the field and said to his sons, ‘A plague of locusts would have left more than this. The hail has left nothing."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db2544e522e8','ch_8d731d1c1d7a','text','{"text": "This year we will have no corn.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d48f673bbe24','ch_8d731d1c1d7a','text','{"text": "That night was a sorrowful one."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9e8354a65da','ch_8d731d1c1d7a','text','{"text": "‘All our work, for nothing.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0c91420b99d','ch_8d731d1c1d7a','text','{"text": "‘There’s no one who can help us.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff1009a9fea4','ch_8d731d1c1d7a','text','{"text": "‘We’ll all go hungry this year.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9b8020cfb80','ch_8d731d1c1d7a','text','{"text": "But in the hearts of all who lived in that solitary house in the middle of the valley, there was a single hope:"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20cd819464b8','ch_8d731d1c1d7a','text','{"text": "help from God."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad5f78a7c114','ch_8d731d1c1d7a','text','{"text": "‘Don’t be so upset, even though this seems like a total loss. Remember, no one dies of hunger.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0eb9113b2112','ch_8d731d1c1d7a','text','{"text": "‘That’s what they say: no one dies of hunger.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d60685b677fd','ch_8d731d1c1d7a','text','{"text": "All through the night, Lencho thought only of his one hope:"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6d0850ae303','ch_8d731d1c1d7a','text','{"text": "the help of God, whose eyes, as he had been instructed, see everything, even what is deep in one’s conscience. Lencho was an ox of a man, working like an animal in the fields, but still he knew how to write. The following Sunday, at daybreak, he began to write a letter which he himself would carry to town and place in the mail. It was nothing less than a letter to God."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f943d0702eb','ch_8d731d1c1d7a','text','{"text": "‘God,’ he wrote, ‘if you don’t help me, my family and I will go hungry this year. I need a hundred pesos in order to sow my field again and to live until the crop comes, because the hailstorm... .’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b53295786f53','ch_8d731d1c1d7a','text','{"text": "He wrote ‘To God’ on the envelope, put the letter inside and, still troubled, went to town."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab41c5bccad5','ch_8d731d1c1d7a','text','{"text": "At the post office, he placed a stamp on the letter and dropped it into the mailbox. One of the employees, who was a postman and also helped at the post office, went to his boss laughing heartily and showed him the letter to God. Never in his career as a postman had he known that address."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e73440cb0b77','ch_8d731d1c1d7a','text','{"text": "The postmaster — a fat, amiable fellow — also broke out laughing, but almost immediately he turned serious and, tapping the letter on his desk, commented, ‘What faith! I wish I had the faith of the man who wrote this letter. Starting up a correspondence with God!’ So, in order not to shake the writer’s faith in God, the postmaster came up with an idea:"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4ccab8c6740','ch_8d731d1c1d7a','text','{"text": "answer the letter. But when he opened it, it was evident that to answer it he needed something more than goodwill, ink and paper."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6011a82079d1','ch_8d731d1c1d7a','text','{"text": "But he stuck to his resolution:"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e56af4f5269','ch_8d731d1c1d7a','text','{"text": "he asked for money from his employees, he himself gave part of his salary, and several friends of his were obliged to give something ‘for an act of charity’."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d861012d3f7','ch_8d731d1c1d7a','text','{"text": "It was impossible for him to gather together the hundred pesos, so he was able to send the farmer only a little more than half. He put the money in an envelope addressed to Lencho and with it a letter containing only a single word as a signature:"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa71d0f983f8','ch_8d731d1c1d7a','text','{"text": "God. The following Sunday Lencho came a bit earlier than usual to ask if there was a letter for him."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c87c09fa150f','ch_8d731d1c1d7a','text','{"text": "It was the postman himself who handed the letter to him while the postmaster, experiencing the contentment of a man who has performed a good deed, looked on from his office. Lencho showed not the slightest surprise on seeing the money; such was his confidence — but he became angry when he counted the money. God could not have made a mistake, nor could he have denied Lencho what he had requested. Immediately, Lencho went up to the window to ask for paper and ink."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_282304716c29','ch_8d731d1c1d7a','text','{"text": "On the public writing-table, he started to write, with much wrinkling of his brow, caused by the effort he had to make to express his ideas. When he finished, he went to the window to buy a stamp which he licked and then affixed to the envelope with a blow of his fist. The moment the letter fell into the mailbox the postmaster went to open it. It said:"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3b4d0609ba5','ch_8d731d1c1d7a','text','{"text": "‘God: Of the money that I asked for, only seventy pesos reached me. Send me the rest, since I need it very much. But don’t send it to me through the mail because the post office employees are a bunch of crooks. Lencho.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b966168bab8','ch_8d731d1c1d7a','text','{"text": "*********"}',32);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_d86f8543a6e7','bk_ncert_english','10-12-dust-of-snow','10.12 Dust of Snow',NULL,'public',34,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67157376f23e','ch_d86f8543a6e7','text','{"text": "The way a crow"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c0cf79b235e','ch_d86f8543a6e7','text','{"text": "Shook down on me"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa4d4987c4d7','ch_d86f8543a6e7','text','{"text": "The dust of snow"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_861df7617adc','ch_d86f8543a6e7','text','{"text": "From a hemlock tree"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ecba7fd4522','ch_d86f8543a6e7','text','{"text": "Has given my heart"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5956ddcc7b23','ch_d86f8543a6e7','text','{"text": "A change of mood"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b54a5da7c46c','ch_d86f8543a6e7','text','{"text": "And saved some part"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bc392dc170e','ch_d86f8543a6e7','text','{"text": "Of a day I had rued."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25c9188dfd8a','ch_d86f8543a6e7','heading','{"level": 2, "text": "Robert Frost"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_599046d865ba','ch_d86f8543a6e7','text','{"text": "*********"}',10);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_d28a33df5ef7','bk_ncert_english','10-13-fire-and-ice','10.13 Fire and Ice',NULL,'public',35,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd99a6acbe16','ch_d28a33df5ef7','text','{"text": "Some say the world will end in fire"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64967fcbdbba','ch_d28a33df5ef7','text','{"text": "Some say in ice."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df717e4d97b2','ch_d28a33df5ef7','text','{"text": "From what I’ve tasted of desire"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_297fbc1c7d18','ch_d28a33df5ef7','text','{"text": "I hold with those who favour fire."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3f5fa794612','ch_d28a33df5ef7','text','{"text": "But if it had to perish twice,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83790ee80c2c','ch_d28a33df5ef7','text','{"text": "I think I know enough of hate"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_651b604c0077','ch_d28a33df5ef7','text','{"text": "To say that for destruction ice"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1561de886b1','ch_d28a33df5ef7','text','{"text": "Is also great"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97a9dbd4c015','ch_d28a33df5ef7','text','{"text": "And would suffice."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3be963ffb6d8','ch_d28a33df5ef7','heading','{"level": 2, "text": "Robert Frost"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1060fe7995c','ch_d28a33df5ef7','text','{"text": "*********"}',11);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_3c3af0e39dd3','bk_ncert_english','10-14-nelson-mandela-long-walk-to-freedom','10.14 Nelson Mandela Long Walk to Freedom',NULL,'public',36,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b29b0821b4a8','ch_3c3af0e39dd3','text','{"text": "TENTH May dawned bright and clear. For the past few days I had been pleasantly besieged by dignitaries and world leaders who were coming to pay their respects before the inauguration. The inauguration would be the largest gathering ever of international leaders on South African soil. The ceremonies took place in the lovely sandstone amphitheatre formed by the Union Buildings in Pretoria."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6dd5c8be958','ch_3c3af0e39dd3','text','{"text": "For decades this had been the seat of white supremacy, and now it was the site of a rainbow gathering of different colours and nations for the installation of South Africa’s first democratic, non-racial government. On that lovely autumn day I was accompanied by my daughter Zenani. On the podium, Mr de Klerk was first sworn in as second deputy president. Then Thabo Mbeki was sworn in as first deputy president."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3edd9ae188a6','ch_3c3af0e39dd3','text','{"text": "When it was my turn, I pledged to obey and uphold the Constitution and to devote myself to the wellbeing of the Republic and its people. To the assembled guests and the watching world, I said:"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9094c1ce3b63','ch_3c3af0e39dd3','text','{"text": "Today, all of us do, by our presence here... confer glory and hope to newborn liberty. Out of the experience of an extraordinary human disaster that lasted too long, must be born a society of which all humanity will be proud."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3be06eabea46','ch_3c3af0e39dd3','text','{"text": "We, who were outlaws not so long ago, have today been given the rare privilege to be host to the nations of the world on our own soil. We thank all of our distinguished international guests for having come to take possession with the people of our country of what is, after all, a common victory for justice, for peace, for human dignity. We have, at last, achieved our political emancipation."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36754250a16e','ch_3c3af0e39dd3','text','{"text": "We pledge ourselves to liberate all our people from the continuing bondage of poverty, deprivation, suffering, gender and other discrimination. Never, never, and never again shall it be that this beautiful land will again experience the oppression of one by another. The sun shall never set on so glorious a human achievement. Let freedom reign."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4036af7bc2bb','ch_3c3af0e39dd3','text','{"text": "God bless Africa! A few moments later we all lifted our eyes in awe as a spectacular array of South African jets, helicopters and troop carriers roared in perfect formation over the Union Buildings. It was not only a display of pinpoint precision and military force, but a demonstration of the military’s loyalty to democracy, to a new government that had been freely and fairly elected."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a04a0ecb262','ch_3c3af0e39dd3','text','{"text": "Only moments before, the highest generals of the South African defence force and police, their chests bedecked with ribbons and medals from days gone by, saluted me and pledged their loyalty. I was not unmindful of the fact that not so many years before they would not have saluted but arrested me. Finally a chevron of Impala jets left a smoke trail of the black, red, green, blue and gold of the new South African flag."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33346b920d94','ch_3c3af0e39dd3','text','{"text": "The day was symbolised for me by the playing of our two national anthems, and the vision of whites singing ‘Nkosi Sikelel –iAfrika’ and blacks singing ‘Die Stem’, the old anthem of the Republic."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef1b84446b63','ch_3c3af0e39dd3','text','{"text": "Although that day neither group knew the lyrics of the anthem they once despised, they would soon know the words by heart. On the day of the inauguration, I was overwhelmed with a sense of history. In the first decade of the twentieth century, a few years after the bitter Anglo-Boer war and before my own birth, the white-skinned peoples of South Africa patched up their differences and erected a system of racial domination against the dark-skinned peoples of their own land."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16ecacf91fcd','ch_3c3af0e39dd3','text','{"text": "The structure they created formed the basis of one of the harshest, most inhumane, societies the world has ever known. Now, in the last decade of the twentieth century, and my own eighth decade as a man, that system had been overturned forever and replaced by one that recognised the rights and freedoms of all peoples, regardless of the colour of their skin."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32629d9edae2','ch_3c3af0e39dd3','text','{"text": "That day had come about through the unimaginable sacrifices of thousands of my people, people whose suffering and courage can never be counted or repaid. I felt that day, as I have on so many other days, that I was simply the sum of all those African patriots who had gone before me. That long and noble line ended and now began again with me. I was pained that I was not able to thank them and that they were not able to see what their sacrifices had wrought."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5cc885dd6443','ch_3c3af0e39dd3','text','{"text": "The policy of apartheid created a deep and lasting wound in my country and my people. All of us will spend many years, if not generations, recovering from that profound hurt."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a26f177d57d8','ch_3c3af0e39dd3','text','{"text": "But the decades of oppression and brutality had another, unintended, effect, and that was that it produced the Oliver Tambos, the Walter Sisulus, the Chief Luthulis, the Yusuf Dadoos, the Bram Fischers, the Robert Sobukwes of our time* — men of such extraordinary courage, wisdom and generosity that their like may never be known again. Perhaps it requires such depths of oppression to create such heights of character."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_403d4f52f7a3','ch_3c3af0e39dd3','text','{"text": "My country is rich in the minerals and gems that lie beneath its soil, but I have always known that its greatest wealth is its people, finer and truer than the purest diamonds. It is from these comrades in the struggle that I learned the meaning of courage. Time and again, I have seen men and women risk and give their lives for an idea. I have seen men stand up to attacks and torture without breaking, showing a strength and resilience that defies the imagination."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05f93174380a','ch_3c3af0e39dd3','text','{"text": "I learned that courage was not the absence of fear, but the triumph over it. The brave man is not he who does not feel afraid, but he who conquers that fear. No one is born hating another person because of the colour of his skin, or his background, or his religion. People must learn to hate, and if they can learn to hate, they can be taught to love, for love comes more naturally to the human heart than its opposite."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40d6e45213b4','ch_3c3af0e39dd3','text','{"text": "Even in the grimmest times in prison, when my comrades and I were pushed to our limits, I would see a glimmer of humanity in one of the guards, perhaps just for a second, but it was enough to reassure me and keep me going. Man’s goodness is a flame that can be hidden but never extinguished. society, each man is able to fulfil those obligations according to his own inclinations and abilities."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f722da3c7859','ch_3c3af0e39dd3','text','{"text": "But in a country like South Africa, it was almost impossible for a man of my birth and colour to fulfil both of those obligations. In South Africa, a man of colour who attempted to live as a human being was punished and isolated. In South Africa, a man who tried to fulfil his duty to his people was inevitably ripped from his family and his home and was forced to live a life apart, a twilight existence of secrecy and rebellion."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40770f49fcdf','ch_3c3af0e39dd3','text','{"text": "I did not in the beginning choose to place my people above my family, but in attempting to serve my people, I found that I was prevented from fulfilling my obligations as a son, a brother, a father and a husband. I was not born with a hunger to be free. I was born free — free in every way that I could know."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1236af344090','ch_3c3af0e39dd3','text','{"text": "Free to run in the fields near my mother’s hut, free to swim in the clear stream that ran through my village, free to roast mealies under the stars and ride the broad backs of slow-moving bulls. As long as I obeyed my father and abided by the customs of my tribe, I was not troubled by the laws of man or God. It was only when I began to learn that my boyhood freedom was an illusion, when I discovered as a young man that my freedom had already been taken from me, that I began to hunger for it."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0105e6925890','ch_3c3af0e39dd3','text','{"text": "At first, as a student, I wanted freedom only for myself, the transitory freedoms of being able to stay out at night, read what I pleased and go where I chose. Later, as a young man in Johannesburg, I yearned for the basic and honourable freedoms of achieving my potential, of earning my keep, of marrying and having a family — the freedom not to be obstructed in a lawful life. But then I slowly saw that not only was I not free, but my brothers and sisters were not free."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7dfa3e2dde87','ch_3c3af0e39dd3','text','{"text": "I saw that it was not just my freedom that was curtailed, but the freedom of everyone who looked like I did. That is when I joined the African National Congress, and that is when the hunger for my own freedom became the greater hunger for the freedom of my people."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfa240401734','ch_3c3af0e39dd3','text','{"text": "It was this desire for the freedom of my people to live their lives with dignity and selfrespect that animated my life, that transformed a frightened young man into a bold one, that drove a law-abiding attorney to become a criminal, that turned a family-loving husband into a man without a home, that forced a life-loving man to live like a monk."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52a193856b75','ch_3c3af0e39dd3','text','{"text": "I am no more virtuous or self-sacrificing than the next man, but I found that I could not even enjoy the poor and limited freedoms I was allowed when I knew my people were not free. Freedom is indivisible; the chains on anyone of my people were the chains on all of them, the chains on all of my people were the chains on me. I knew that the oppressor must be liberated just as surely as the oppressed."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1aaa17dc879','ch_3c3af0e39dd3','text','{"text": "A man who takes away another man’s freedom is a prisoner of hatred; he is locked behind the bars of prejudice and narrowmindedness. I am not truly free if I am taking away someone else’s freedom, just as surely as I am not free when my freedom is taken from me. The oppressed and the oppressor alike are robbed of their humanity."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_320b43cca388','ch_3c3af0e39dd3','text','{"text": "Nelson Rolihlahla Mandela"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d42b191c67b','ch_3c3af0e39dd3','text','{"text": "*********"}',27);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_6e685a9f7e5b','bk_ncert_english','10-15-two-stories-about-flying','10.15 Two Stories about Flying',NULL,'public',37,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbe2cfa012e4','ch_6e685a9f7e5b','heading','{"level": 2, "text": "I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe546259a4bc','ch_6e685a9f7e5b','text','{"text": "His First Flight"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af5647b5c93d','ch_6e685a9f7e5b','text','{"text": "THE young seagull was alone on his ledge. His two brothers and his sister had already flown away the day before. He had been afraid to fly with them. Somehow when he had taken a little run forward to the brink of the ledge and attempted to flap his wings he became afraid. The great expanse of sea stretched down beneath, and it was such a long way down — miles down."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0e1ee57c2c0','ch_6e685a9f7e5b','text','{"text": "He felt certain that his wings would never support him; so he bent his head and ran away back to the little hole under the ledge where he slept at night. Even when each of his brothers and his little sister, whose wings were far shorter than his own, ran to the brink, flapped their wings, and flew away, he failed to muster up courage to take that plunge which appeared to him so desperate."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_858cbdcf247d','ch_6e685a9f7e5b','text','{"text": "His father and mother had come around calling to him shrilly, upbraiding him, threatening to let him starve on his ledge unless he flew away. But for the life of him he could not move. That was twenty-four hours ago. Since then nobody had come near him. The day before, all day long, he had watched his parents flying about with his brothers and sister, perfecting them in the art of flight, teaching them how to skim the waves and how to dive for fish."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f1926ecc96e','ch_6e685a9f7e5b','text','{"text": "He had, in fact, seen his older brother catch his first herring and devour it, standing on a rock, while his parents circled around raising a proud cackle. And all the morning the whole family had walked about on the big plateau midway down the opposite cliff taunting him with his cowardice. The sun was now ascending the sky, blazing on his ledge that faced the south. He felt the heat because he had not eaten since the previous nightfall."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_232266f3c180','ch_6e685a9f7e5b','text','{"text": "He stepped slowly out to the brink of the ledge, and standing on one leg with the other leg hidden under his wing, he closed one eye, then the other, and pretended to be falling asleep. Still they took no notice of him. He saw his two brothers and his sister lying on the plateau dozing with their heads sunk into their necks. His father was preening the feathers on his white back. Only his mother was looking at him."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b6ff3d6915c','ch_6e685a9f7e5b','text','{"text": "She was standing on a little high hump on the plateau, her white breast thrust forward. Now and again, she tore at a piece of fish that lay at her feet and then scrapped each side of her beak on the rock. The sight of the food maddened him. How he loved to tear food that way, scrapping his beak now and again to whet it."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a07d9719d58','ch_6e685a9f7e5b','text','{"text": "‘Ga, ga, ga,’ he cried begging her to bring him some food."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1a5c93e368f','ch_6e685a9f7e5b','text','{"text": "‘Gaw-col-ah,’ she screamed back derisively. But he kept calling plaintively, and after a minute or so he uttered a joyful scream. His mother had picked up a piece of the fish and was flying across to him with it. He leaned out eagerly, tapping the rock with his feet, trying to get nearer to her as she flew across. But when she was just opposite to him, she halted, her wings motionless, the piece of fish in her beak almost within reach of his beak."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e24b3e351549','ch_6e685a9f7e5b','text','{"text": "He waited a moment in surprise, wondering why she did not come nearer, and then, maddened by hunger, he dived at the fish. With a loud scream he fell outwards and downwards into space. Then a monstrous terror seized him and his heart stood still. He could hear nothing. But it only lasted a minute. The next moment he felt his wings spread outwards. The wind rushed against his breast feathers, then under his stomach, and against his wings."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99cb0f4d13f2','ch_6e685a9f7e5b','text','{"text": "He could feel the tips of his wings cutting through the air. He was not falling headlong now. He was soaring gradually downwards and outwards. He was no longer afraid. He just felt a bit dizzy. Then he flapped his wings once and he soared upwards."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8e5098f5215','ch_6e685a9f7e5b','text','{"text": "‘Ga, ga, ga, Ga, ga, ga, Gaw-col-ah,’ his mother swooped past him, her wings making a loud noise."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1ff1e3dffbf','ch_6e685a9f7e5b','text','{"text": "He answered her with another scream. Then his father flew over him screaming. He saw his two brothers and his sister flying around him curveting and banking and soaring and diving. Then he completely forgot that he had not always been able to fly, and commended himself to dive and soar and curve, shrieking shrilly. He was near the sea now, flying straight over it, facing straight out over the ocean."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0efaecc62527','ch_6e685a9f7e5b','text','{"text": "He saw a vast green sea beneath him, with little ridges moving over it and he turned his beak sideways and cawed amusedly. His parents and his brothers and sister had landed on this green flooring ahead of him. They were beckoning to him, calling shrilly. He dropped his legs to stand on the green sea. His legs sank into it. He screamed with fright and attempted to rise again flapping his wings. But he was tired and weak with hunger and he could not rise, exhausted by the strange exercise."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b035e42ed6c','ch_6e685a9f7e5b','text','{"text": "His feet sank into the green sea, and then his belly touched it and he sank no farther. He was floating on it, and around him his family was screaming, praising him and their beaks were offering him scraps of dog-fish. He had made his first flight."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f976d7976969','ch_6e685a9f7e5b','text','{"text": "Liam O’ Flaherty"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d086906143a2','ch_6e685a9f7e5b','heading','{"level": 2, "text": "Ii"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c7dbd8a475f','ch_6e685a9f7e5b','text','{"text": "The Black Aeroplane"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5df20e7f4426','ch_6e685a9f7e5b','text','{"text": "THE moon was coming up in the east, behind me, and stars were shining in the clear sky above me. There wasn’t a cloud in the sky. I was happy to be alone high up above the sleeping countryside."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7eac77cbc3cd','ch_6e685a9f7e5b','text','{"text": "I was flying my old Dakota aeroplane over France back to England. I was dreaming of my holiday and looking forward to being with my family. I looked at my watch:"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7921311f8775','ch_6e685a9f7e5b','text','{"text": "one thirty in the morning."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e121d0dd8de','ch_6e685a9f7e5b','text','{"text": "‘I should call Paris Control soon,’ I thought."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00d5bd0c93aa','ch_6e685a9f7e5b','text','{"text": "As I looked down past the nose of the aeroplane, I saw the lights of a big city in front of me. I switched on the radio and said, ‘Paris Control, Dakota DS 088 here. Can you hear me? I’m on my way to England. Over.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d17ab032584','ch_6e685a9f7e5b','text','{"text": "The voice from the radio answered me immediately:"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6b9a093b49f','ch_6e685a9f7e5b','text','{"text": "‘DS 088, I can hear you. You ought to turn twelve degrees west now, DS 088. Over.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01b404cb9a3c','ch_6e685a9f7e5b','text','{"text": "I checked the map and the compass, switched over to my second and last fuel tank, and turned the Dakota twelve degrees west towards England."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdf9c0d7ba7d','ch_6e685a9f7e5b','text','{"text": "‘I’ll be in time for breakfast,’ I thought. A good big English breakfast! Everything was going well — it was an easy flight. Paris was about 150 kilometres behind me when I saw the clouds. Storm clouds. They were huge. They looked like black mountains standing in front of me across the sky. I knew I could not fly up and over them, and I did not have enough fuel to fly around them to the north or south."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_814de2c36688','ch_6e685a9f7e5b','text','{"text": "‘I ought to go back to Paris,’ I thought, but I wanted to get home."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78624cb8f38a','ch_6e685a9f7e5b','text','{"text": "I wanted that breakfast."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea94d76068c9','ch_6e685a9f7e5b','text','{"text": "‘I’ll take the risk,’ I thought, and flew that old Dakota straight into the storm. Inside the clouds, everything was suddenly black. It was impossible to see anything outside the aeroplane. The old aeroplane jumped and twisted in the air. I looked at the compass. I couldn’t believe my eyes:"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0c2fe4d9e28','ch_6e685a9f7e5b','text','{"text": "the compass was turning round and round and round. It was dead. It would not work! The other instruments were suddenly dead, too. I tried the radio."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_357b444cbe5a','ch_6e685a9f7e5b','text','{"text": "‘Paris Control? Paris Control? Can you hear me?’ There was no answer."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6bbd83fcc4c9','ch_6e685a9f7e5b','text','{"text": "The radio was dead too. I had no radio, no compass, and I could not see where I was. I was lost in the storm. Then, in the black clouds quite near me, I saw another aeroplane. It had no lights on its wings, but I could see it flying next to me through the storm. I could see the pilot’s face — turned towards me. I was very glad to see another person. He lifted one hand and waved."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d49325b4fb8a','ch_6e685a9f7e5b','text','{"text": "‘Follow me,’ he was saying."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92880f10811f','ch_6e685a9f7e5b','text','{"text": "‘Follow me.’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc915a49ce64','ch_6e685a9f7e5b','text','{"text": "‘He knows that I am lost,’ I thought."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_891b70aacb92','ch_6e685a9f7e5b','text','{"text": "‘He’s trying to help me.’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28d52c648d21','ch_6e685a9f7e5b','text','{"text": "He turned his aeroplane slowly to the north, in front of my Dakota, so that it would be easier for me to follow him. I was very happy to go behind the strange aeroplane like an obedient child. After half an hour the strange black aeroplane was still there in front of me in the clouds. Now there was only enough fuel in the old Dakota’s last tank to fly for five or ten minutes more. I was starting to feel frightened again. But then he started to go down and I followed through the storm."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef75f748b96e','ch_6e685a9f7e5b','text','{"text": "Suddenly I came out of the clouds and saw two long straight lines of lights in front of me. It was a runway! An airport! I was safe! I turned to look for my friend in the black aeroplane, but the sky was empty. There was nothing there. The black aeroplane was gone. I could not see it anywhere. I landed and was not sorry to walk away from the old Dakota near the control tower. I went and asked a woman in the control centre where I was and who the other pilot was. I wanted to say"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3768d663218d','ch_6e685a9f7e5b','text','{"text": "‘Thank you’."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac15323a945b','ch_6e685a9f7e5b','text','{"text": "She looked at me very strangely, and then laughed."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d684270cb07c','ch_6e685a9f7e5b','text','{"text": "‘Another aeroplane? Up there in this storm? No other aeroplanes were flying tonight. Yours was the only one I could see on the radar.’"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c1abceff082','ch_6e685a9f7e5b','text','{"text": "So who helped me to arrive there safely without a compass or a radio, and without any more fuel in my tanks? Who was the pilot on the strange black aeroplane, flying in the storm, without lights?"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c92c6be0041','ch_6e685a9f7e5b','text','{"text": "Frederick Forsyth"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a01aa5ef0ae','ch_6e685a9f7e5b','text','{"text": "*********"}',46);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_f41bdeeb19bc','bk_ncert_english','10-16-how-to-tell-wild-animals','10.16 How to Tell Wild Animals',NULL,'public',38,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66825da64bf0','ch_f41bdeeb19bc','text','{"text": "If ever you should go by chance"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2d3e4ebecc0','ch_f41bdeeb19bc','text','{"text": "To jungles in the east;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b4600151740','ch_f41bdeeb19bc','text','{"text": "And if there should to you advance"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa86e4354b74','ch_f41bdeeb19bc','text','{"text": "A large and tawny beast,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_784b5f46d05b','ch_f41bdeeb19bc','text','{"text": "If he roars at you as you’re dyin’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54d4d82d3c90','ch_f41bdeeb19bc','text','{"text": "You’ll know it is the Asian Lion..."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fb03b6f7c79','ch_f41bdeeb19bc','text','{"text": "Or if some time when roaming round,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5124e8c5a93','ch_f41bdeeb19bc','text','{"text": "A noble wild beast greets you,"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_114c6e511f72','ch_f41bdeeb19bc','text','{"text": "With black stripes on a yellow ground,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac2cfe738f27','ch_f41bdeeb19bc','text','{"text": "Just notice if he eats you."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b4b8a93d7c8','ch_f41bdeeb19bc','text','{"text": "This simple rule may help you learn"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ded1b0c679e6','ch_f41bdeeb19bc','text','{"text": "The Bengal Tiger to discern."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6d66034569d','ch_f41bdeeb19bc','text','{"text": "If strolling forth, a beast you view,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0e84f32f0c0','ch_f41bdeeb19bc','text','{"text": "Whose hide with spots is peppered,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_910f1d13cab0','ch_f41bdeeb19bc','text','{"text": "As soon as he has lept on you,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ecc05ad6662b','ch_f41bdeeb19bc','text','{"text": "You’ll know it is the Leopard."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c8a7bc828f4','ch_f41bdeeb19bc','text','{"text": "’Twill do no good to roar with pain,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9073a1922c7c','ch_f41bdeeb19bc','text','{"text": "He’ll only lep and lep again."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc27ce001777','ch_f41bdeeb19bc','text','{"text": "If when you’re walking round your yard"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf850bb875d8','ch_f41bdeeb19bc','text','{"text": "You meet a creature there,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72f514937b77','ch_f41bdeeb19bc','text','{"text": "Who hugs you very, very hard,"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de4f179f8649','ch_f41bdeeb19bc','text','{"text": "Be sure it is a Bear."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c50ef7d735f','ch_f41bdeeb19bc','text','{"text": "If you have any doubts, I guess"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1662d724e91','ch_f41bdeeb19bc','text','{"text": "He’ll give you just one more caress."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c47cbb83f9f','ch_f41bdeeb19bc','text','{"text": "Though to distinguish beasts of prey"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a54426bbb8ea','ch_f41bdeeb19bc','text','{"text": "A novice might nonplus,"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1815b7b8f384','ch_f41bdeeb19bc','text','{"text": "The Crocodile you always may"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7b5068e936d','ch_f41bdeeb19bc','text','{"text": "Tell from the Hyena thus:"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b5be39c8537','ch_f41bdeeb19bc','text','{"text": "Hyenas come with merry smiles;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2195d85190c1','ch_f41bdeeb19bc','text','{"text": "But if they weep they’re Crocodiles."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21576adaacda','ch_f41bdeeb19bc','text','{"text": "The true Chameleon is small,"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1386c4b14040','ch_f41bdeeb19bc','text','{"text": "A lizard sort of thing;"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8d1bca7bcf4','ch_f41bdeeb19bc','text','{"text": "He hasn’t any ears at all,"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92ea1f4d7269','ch_f41bdeeb19bc','text','{"text": "And not a single wing."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eec9bb9cf4f3','ch_f41bdeeb19bc','text','{"text": "If there is nothing on the tree,"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21dcea9326f8','ch_f41bdeeb19bc','text','{"text": "’Tis the chameleon you see."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b5e2f72b9a2','ch_f41bdeeb19bc','heading','{"level": 2, "text": "Carolyn Wells"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e718922fbdc0','ch_f41bdeeb19bc','text','{"text": "*********"}',38);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_206ca47538a4','bk_ncert_english','10-17-the-ball-poem','10.17 The Ball Poem',NULL,'public',39,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_959f59eb500d','ch_206ca47538a4','text','{"text": "What is the boy now, who has lost his ball,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed5ad8fd2790','ch_206ca47538a4','text','{"text": "What, what is he to do? I saw it go"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a48549033dc1','ch_206ca47538a4','text','{"text": "Merrily bouncing, down the street, and then"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4143053df9f','ch_206ca47538a4','text','{"text": "Merrily over — there it is in the water!"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_892e2d028620','ch_206ca47538a4','text','{"text": "No use to say ‘O there are other balls’:"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e84a8df3de2','ch_206ca47538a4','text','{"text": "An ultimate shaking grief fixes the boy"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fb4f667b4e1','ch_206ca47538a4','text','{"text": "As he stands rigid, trembling, staring down"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ebb99fff9258','ch_206ca47538a4','text','{"text": "All his young days into the harbour where"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_041832cf98d6','ch_206ca47538a4','text','{"text": "His ball went. I would not intrude on him;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0549f5ead038','ch_206ca47538a4','text','{"text": "A dime, another ball, is worthless. Now"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcf98cb64db2','ch_206ca47538a4','text','{"text": "He senses first responsibility"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7fbe609e51f7','ch_206ca47538a4','text','{"text": "In a world of possessions. People will take"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2919dbd9bfd6','ch_206ca47538a4','text','{"text": "Balls, balls will be lost always, little boy."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6961266f92f','ch_206ca47538a4','text','{"text": "And no one buys a ball back. Money is external."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_039af6187d6f','ch_206ca47538a4','text','{"text": "He is learning, well behind his desperate eyes,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dd2b2cb4d08','ch_206ca47538a4','text','{"text": "The epistemology of loss, how to stand up"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c54f38432d4a','ch_206ca47538a4','text','{"text": "Knowing what every man must one day know"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2b21d14e0e9','ch_206ca47538a4','text','{"text": "And most know many days, how to stand up."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ae1a119245b','ch_206ca47538a4','heading','{"level": 2, "text": "John Berryman"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ebedd7ea5d0','ch_206ca47538a4','text','{"text": "*********"}',20);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_1eec1ce88d32','bk_ncert_english','10-18-from-the-diary-of-anne-frank','10.18 From the Diary of Anne Frank',NULL,'public',40,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3684d29f6622','ch_1eec1ce88d32','text','{"text": "Before You Read"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_552086184c24','ch_1eec1ce88d32','text','{"text": "Anneliese Marie ‘Anne’ Frank (12 June 1929 – February/March 1945) was a German – born Jewish girl who wrote while in hiding with her family and four friends in Amsterdam during the German occupation of the Netherlands in World War II. Her family had moved to Amsterdam after the Nazis gained power in Germany but were trapped when the Nazi occupation extended into the Netherlands."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90adeaa1ee56','ch_1eec1ce88d32','text','{"text": "As persecutions against the Jewish population increased, the family went into hiding in July 1942 in hidden rooms in her father Otto Frank’s office building. After two years in hiding, the group was betrayed and transported to the concentration camp system where Anne died of typhus in Bergen-Belsen within days of her sister, Margot Frank. Her father, Otto, the only survivor of the group, returned to Amsterdam after the war ended, to find that her diary had been saved."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd197c780c06','ch_1eec1ce88d32','text','{"text": "Convinced that it was a unique record, he took action to have it published in English under the name The Diary of a Young Girl. The diary was given to Anne Frank for her thirteenth birthday and chronicles the events of her life from 12 June 1942 until its final entry of 1 August 1944. It was eventually translated from its original Dutch into many languages and became one of the world’s most widely read books."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7dec0e7981b1','ch_1eec1ce88d32','text','{"text": "There have also been several films, television and theatrical productions, and even an opera, based on the diary. Described as the work of a mature and insightful mind, the diary provides an intimate examination of daily life under Nazi occupation. Anne Frank has become one of the most renowned and discussed of the Holocaust victims."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_637d3fe29a18','ch_1eec1ce88d32','text','{"text": "WRITING in a diary is a really strange experience for someone like me. Not only because I’ve never written anything before, but also because it seems to me that later on neither I nor anyone else will be interested in the musings of a thirteen-year-old schoolgirl. Oh well, it doesn’t matter. I feel like writing, and I have an even greater need to get all kinds of things off my chest."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a7a0317730d','ch_1eec1ce88d32','text','{"text": "‘Paper has more patience than people.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5691744733af','ch_1eec1ce88d32','text','{"text": "I thought of this saying on one of those days when I was feeling a little depressed and was sitting at home with my chin in my hands, bored and listless, wondering whether to stay in or go out. I finally stayed where I was, brooding:"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd2f5a822e5c','ch_1eec1ce88d32','text','{"text": "Yes, paper does have more patience, and since I’m not planning to let anyone else read this stiff-backed notebook grandly referred to as a ‘diary’, unless I should ever find a real friend, it probably won’t make a bit of difference. Now I’m back to the point that prompted me to keep a diary in the first place:"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d812431fd6a','ch_1eec1ce88d32','text','{"text": "I don’t have a friend. Let me put it more clearly, since no one will believe that a thirteen-year-old girl is completely alone in the world. And I’m not. I have loving parents and a sixteen-year-old sister, and there are about thirty people I can call friends. I have a family, loving aunts and a good home."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd76b4c894b6','ch_1eec1ce88d32','text','{"text": "No, on the surface I seem to have everything, except my one true friend. All I think about when I’m with friends is having a good time. I can’t bring myself to talk about anything but ordinary everyday things. We don’t seem to be able to get any closer, and that’s the problem. Maybe it’s my fault that we don’t confide in each other. In any case, that’s just how things are, and unfortunately they’re not liable to change. This is why I’ve started the diary."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2afbcf1a602f','ch_1eec1ce88d32','text','{"text": "To enhance the image of this long-awaited friend in my imagination, I don’t want to jot down the facts in this diary the way most people would do, but I want the diary to be my friend, and I’m going to call this friend ‘Kitty’. Since no one would understand a word of my stories to Kitty if I were to plunge right in, I’d better provide a brief sketch of my life, much as I dislike doing so. My father, the most adorable father I’ve ever seen, didn’t marry my mother until he was thirty-six and she was twenty-five. My sister, Margot, was born in Frankfurt in Germany in 1926. I was born on 12 June 1929. I lived in Frankfurt until I was four. My father emigrated to Holland in 1933."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a2b431c0b71','ch_1eec1ce88d32','text','{"text": "My mother, Edith Hollander Frank, went with him to Holland in September, while Margot and I were sent to Aachen to stay with our grandmother. Margot went to Holland in December, and I followed in February, when I was plunked down on the table as a birthday present for Margot. I started right away at the Montessori nursery school. I stayed there until I was six, at which time I started in the first form. In the sixth form my teacher was Mrs Kuperus, the headmistress."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59ddfcc10c28','ch_1eec1ce88d32','text','{"text": "At the end of the year we were both in tears as we said a heartbreaking farewell. In the summer of 1941 Grandma fell ill and had to have an operation, so my birthday passed with little celebration. Grandma died in January 1942. No one knows how often I think of her and still love her. This birthday celebration in 1942 was intended to make up for the other, and Grandma’s candle was lit along with the rest."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04a4229a7e67','ch_1eec1ce88d32','text','{"text": "The four of us are still doing well, and that brings me to the present date of 20 June 1942, and the solemn dedication of my diary."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b890a2441caa','ch_1eec1ce88d32','text','{"text": "Dearest Kitty,"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b6f537d5d58','ch_1eec1ce88d32','text','{"text": "Our entire class is quaking in its boots. The reason, of course, is the forthcoming meeting in which the teachers decide who’ll move up to the next form and who’ll be kept back. Half the class is making bets. G.N. and I laugh ourselves silly at the two boys behind us, C.N. and Jacques, who have staked their entire holiday savings on their bet."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fef4717fccdb','ch_1eec1ce88d32','text','{"text": "From morning to night, it’s ‘You’re going to pass’, ‘No, I’m not’, ‘Yes, you are’, ‘No, I’m not’. Even G.’s pleading glances and my angry outbursts can’t calm them down. If you ask me, there are so many dummies that about a quarter of the class should be kept back, but teachers are the most unpredictable creatures on earth. I’m not so worried about my girlfriends and myself. We’ll make it. The only subject I’m not sure about is maths. Anyway, all we can do is wait. Until then, we keep telling each other not to lose heart. I get along pretty well with all my teachers."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf5edc0c5b7a','ch_1eec1ce88d32','text','{"text": "There are nine of them, seven men and two women. Mr Keesing, the old fogey who teaches maths, was annoyed with me for ages because I talked so much. After several warnings, he assigned me extra homework. An essay on the subject, ‘A Chatterbox’. A chatterbox — what can you write about that? I’d worry about that later, I decided. I jotted down the title in my notebook, tucked it in my bag and tried to keep quiet."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a95bd9b3dd8','ch_1eec1ce88d32','text','{"text": "That evening, after I’d finished the rest of my homework, the note about the essay caught my eye. I began thinking about the subject while chewing the tip of my fountain pen. Anyone could ramble on and leave big spaces between the words, but the trick was to come up with convincing arguments to prove the necessity of talking. I thought and thought, and suddenly I had an idea. I wrote the three pages Mr Keesing had assigned me and was satisfied."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90f7bd10b8ff','ch_1eec1ce88d32','text','{"text": "I argued that talking is a student’s trait and that I would do my best to keep it under control, but that I would never be able to cure myself of the habit since my mother talked as much as I did if not more, and that there’s not much you can do about inherited traits. Mr Keesing had a good laugh at my arguments, but when I proceeded to talk my way through the next lesson, he assigned me a second essay. This time it was supposed to be on ‘An Incorrigible Chatterbox’."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2bf68b3a6f79','ch_1eec1ce88d32','text','{"text": "I handed it in, and Mr Keesing had nothing to complain about for two whole lessons. However, during the third lesson he’d finally had enough."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca87d54d18a5','ch_1eec1ce88d32','text','{"text": "‘Anne Frank, as punishment for talking in class, write an essay entitled —"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6afdc85356bb','ch_1eec1ce88d32','text','{"text": "‘Quack, Quack, Quack, Said Mistress Chatterbox’.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18f2523ff469','ch_1eec1ce88d32','text','{"text": "The class roared. I had to laugh too, though I’d nearly exhausted my ingenuity on the topic of chatterboxes. It was time to come up with something else, something original. My friend, Sanne, who’s good at poetry, offered to help me write the essay from beginning to end in verse and I jumped for joy. Mr Keesing was trying to play a joke on me with this ridiculous subject, but I’d make sure the joke was on him."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b85bfe6af476','ch_1eec1ce88d32','text','{"text": "I finished my poem, and it was beautiful! It was about a mother duck and a father swan with three baby ducklings who were bitten to death by the father because they quacked too much. Luckily, Mr Keesing took the joke the right way. He read the poem to the class, adding his own comments, and to several other classes as well. Since then I’ve been allowed to talk and haven’t been assigned any extra homework. On the contrary, Mr Keesing’s always making jokes these days."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d8519074c67','ch_1eec1ce88d32','text','{"text": "Yours,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7eb74c6e2cf2','ch_1eec1ce88d32','text','{"text": "Anne"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4caa8d257840','ch_1eec1ce88d32','text','{"text": "[Extracted from The Diary of a Young Girl, with slight adaptation]"}',29);
